const linear3=(A,b)=>{A=A.map((r,i)=>[...r,b[i]]);for(let j=0;j<3;j++){let pivot=j;for(let i=j+1;i<3;i++)if(Math.abs(A[i][j])>Math.abs(A[pivot][j]))pivot=i;[A[j],A[pivot]]=[A[pivot],A[j]];if(Math.abs(A[j][j])<1e-15)return [null,null,null];const v=A[j][j];for(let n=j;n<4;n++)A[j][n]/=v;for(let i=0;i<3;i++)if(i!==j){const a=A[i][j];for(let n=j;n<4;n++)A[i][n]-=a*A[j][n];}}return A.map(r=>r[3]);};
function integrate(t,initial,derivative,dt=.015){const n=Math.max(1,Math.min(3000,Math.ceil(t/dt))),step=t/n;let y=[...initial];for(let j=0;j<n;j++){const a=derivative(j*step,y),b=derivative((j+.5)*step,y.map((v,i)=>v+a[i]*step/2)),d=derivative((j+.5)*step,y.map((v,i)=>v+b[i]*step/2)),e=derivative((j+1)*step,y.map((v,i)=>v+d[i]*step));y=y.map((v,i)=>v+step*(a[i]+2*b[i]+2*d[i]+e[i])/6);}return y;}
// Stable step response of two buffered RC stages. Distances in parameter space
// are dimensionless; no absolute near-equality epsilon changes the model.
function bufferedRCStep(t,tau1,tau2){
 const slow=Math.max(tau1,tau2),fast=Math.min(tau1,tau2),x=t/slow,z=t*(slow-fast)/(slow*fast);
 if(t===0)return 0;
 if(x<1e-3&&z<1e-3){
  let a=x*x/2,b=z/2,totalA=a,totalB=b;
  for(let n=3;n<=12;n++){a*=x/n;totalA+=a;}
  for(let n=2;n<=12;n++){b*=-z/(n+1);totalB+=b;}
  return Math.exp(-x)*(totalA+x*totalB);
 }
 const relative=z===0?1:-Math.expm1(-z)/z;
 return -Math.expm1(-x)-x*Math.exp(-x)*relative;
}
