add('rolling_race','Đĩa, vành và cầu lăn trên dốc','Cơ học','rotating',[p('angle','Góc dốc',5,55,20,'°',1),p('distance','Quãng đường trên dốc',.2,4,2,'m',.1)],[q('sphereTime','Thời gian cầu đặc','s'),q('diskTime','Thời gian đĩa đặc','s'),q('ringTime','Thời gian vành','s')],'a = g sinθ/(1+I/(mR²))',s=>{const a=g*Math.sin(rad(s.angle));return {sphereTime:Math.sqrt(2*s.distance*1.4/a),diskTime:Math.sqrt(2*s.distance*1.5/a),ringTime:Math.sqrt(4*s.distance/a)};},'Khối lượng và bán kính có quyết định thứ tự về đích khi lăn không trượt không?',{grade:10,view:'race',limit:'Ba vật bắt đầu từ nghỉ, cùng quãng đường; đủ ma sát tĩnh để lăn không trượt; bỏ qua cản lăn.'});
add('angular_momentum','Thu tay trên đĩa quay','Cơ học','rotating',[p('radius','Bán kính hai vật cầm tay',.2,1.2,.6,'m',.05),p('handMass','Khối lượng mỗi vật',.5,5,2,'kg',.1),p('omega0','Tốc độ góc lúc tay ở 1 m',.2,5,1,'rad/s',.1),p('inertia','Mômen quán tính nền',.5,4,1,'kg·m²',.1)],[q('omega','Tốc độ góc mới','rad/s'),q('momentum','Mômen động lượng','kg·m²/s'),q('work','Công người thực hiện','J')],'Iω = I₀ω₀; ΔK = L²(1/I−1/I₀)/2',s=>{const I0=s.inertia+2*s.handMass,I=s.inertia+2*s.handMass*s.radius**2,L=I0*s.omega0;return {omega:L/I,momentum:L,work:L*L/2*(1/I-1/I0)};},'Động năng quay tăng lấy năng lượng từ đâu khi người thu tay?',{grade:10,view:'arms',limit:'Không có mômen ngoại lực quanh trục đứng; hai vật cầm tay là chất điểm, nền có mômen quán tính cố định.'});
add('atwood_inertia','Máy Atwood với ròng rọc có quán tính','Cơ học','rotating',[p('pulleyMass','Khối lượng ròng rọc đặc',0,5,1,'kg',.1),p('m1','Khối lượng trái',.2,3,1,'kg',.1),p('m2','Khối lượng phải',.2,3,2,'kg',.1)],[q('acc','Gia tốc bên phải đi xuống','m/s²'),q('tension1','Lực căng trái','N'),q('tension2','Lực căng phải','N')],'a = (m₂−m₁)g/(m₁+m₂+Mp/2)',s=>{const acc=(s.m2-s.m1)*g/(s.m1+s.m2+.5*s.pulleyMass);return {acc,tension1:s.m1*(g+acc),tension2:s.m2*(g-acc)};},'Vì sao hai lực căng khác nhau khi ròng rọc có mômen quán tính?',{grade:10,view:'pulley',limit:'Ròng rọc là đĩa đồng chất, dây không trượt; không ma sát ở trục.'});
add('gyroscope','Tiến động chậm của con quay','Cơ học','rotating',[p('omega','Tốc độ quay riêng',10,200,80,'rad/s',5),p('radius','Bán kính đĩa',.05,.3,.15,'m',.01),p('arm','Khoảng cách trục tới trọng tâm',.02,.15,.05,'m',.01)],[q('precession','Tốc độ tiến động','rad/s'),q('ratio','Tỉ số tiến động / quay'),q('period','Chu kì tiến động','s')],'Ω ≈ mgr/(Iω) = 2gr/(R²ω)',s=>{const precession=2*g*s.arm/(s.radius**2*s.omega);const ratio=precession/s.omega;return {precession:ratio<=.1?precession:null,ratio,period:ratio<=.1?2*pi/precession:null};},'Quay riêng nhanh hơn làm con quay tiến động nhanh hơn hay chậm hơn?',{grade:10,view:'gyro',limit:'Đĩa đặc, trục gần ngang, tiến động chậm; chỉ hiển thị nghiệm xấp xỉ khi Ω/ω ≤ 0,1; tỉ số ngoài miền là chẩn đoán từ công thức thử; bỏ qua chương động.'});
// 05. Gravity beyond a point-mass circular orbit.
add('rotating_planet','Trọng trường trên hành tinh quay','Cơ học','orbit',[p('latitude','Vĩ độ',0,90,0,'°',2),p('period','Chu kì quay',4,48,24,'giờ',1)],[q('effective','Thành phần trọng trường theo bán kính','m/s²'),q('centrifugal','Thành phần ly tâm theo bán kính','m/s²'),q('gravity','Hấp dẫn tại bề mặt','m/s²')],'grad = GM/R² − ω²R cos²φ',s=>{const gravity=G*5.972e24/(6371e3)**2,centrifugal=(2*pi/(s.period*3600))**2*6371e3*Math.cos(rad(s.latitude))**2;return {effective:gravity-centrifugal,centrifugal,gravity};},'Vì sao số chỉ cân tại xích đạo và cực có thể khác nhau?',{grade:10,view:'planet',limit:'Hành tinh hình cầu cứng có khối lượng/bán kính Trái Đất; chỉ xét thành phần theo bán kính, bỏ qua độ dẹt.'});
add('elliptic_orbit','Vệ tinh trên quỹ đạo elip','Cơ học','orbit',[p('angle','Góc quỹ đạo từ cận điểm',0,360,60,'°',5),p('eccentricity','Độ lệch tâm',0,.7,.3,'',.02),p('axis','Bán trục lớn',8000,30000,12000,'km',500,0)],[q('speed','Tốc độ quỹ đạo','km/s'),q('radius','Khoảng cách tới tâm','km'),q('areaRate','Tốc độ quét diện tích','km²/s')],'r = a(1−e²)/(1+e cosθ); v² = GM(2/r−1/a)',s=>{const a=s.axis*1000,r=a*(1-s.eccentricity**2)/(1+s.eccentricity*Math.cos(rad(s.angle))),GM=G*5.972e24;const pericenter=s.axis*(1-s.eccentricity),domainValid=pericenter>=6371;return {radius:domainValid?r/1000:null,speed:domainValid?Math.sqrt(GM*(2/r-1/a))/1000:null,areaRate:domainValid?Math.sqrt(GM*a*(1-s.eccentricity**2))/2e6:null,pericenter,domainValid,domainMessage:domainValid?'':'Quỹ đạo đi vào Trái Đất: cần a(1−e) ≥ 6371 km. Hãy tăng bán trục lớn hoặc giảm độ lệch tâm.'};},'Tốc độ thay đổi nhưng tốc độ quét diện tích có đổi theo vị trí không?',{grade:10,view:'ellipse',limit:'Vệ tinh không đáng kể khối lượng, Trái Đất có khối lượng 5,972×10²⁴ kg và bán kính quy ước 6371 km. Chỉ dùng quỹ đạo có a(1−e) ≥ 6371 km; không xét lực cản hay nhiễu loạn.'});
add('binary_orbit','Hai thiên thể quanh khối tâm','Cơ học','orbit',[p('massRatio','Khối lượng thiên thể 2 / 1',.1,2,.5,'',.05),p('separation','Khoảng cách hai tâm',.5,5,2,'10⁸ m',.1)],[q('period','Chu kì chung','giờ'),q('r1','Bán kính quỹ đạo thiên thể 1','10⁸ m'),q('r2','Bán kính quỹ đạo thiên thể 2','10⁸ m')],'ω² = G(M₁+M₂)/d³; M₁r₁ = M₂r₂',s=>({period:2*pi*Math.sqrt((s.separation*1e8)**3/(G*5.972e24*(1+s.massRatio)))/3600,r1:s.separation*s.massRatio/(1+s.massRatio),r2:s.separation/(1+s.massRatio)}),'Thiên thể nặng hơn nằm gần khối tâm hơn như thế nào?',{grade:10,view:'binary',limit:'Hai thiên thể coi như chất điểm; quỹ đạo tròn, M₁=5,972×10²⁴ kg; không thể suy ra bán kính thiên thể từ hình.'});
add('hohmann','Chuyển quỹ đạo Hohmann','Cơ học','orbit',[p('target','Bán kính quỹ đạo đích',8000,42000,14000,'km',500,0),p('start','Bán kính quỹ đạo đầu',6500,7500,7000,'km',100,0)],[q('deltaV','Tổng độ tăng tốc cần thiết','km/s'),q('transferTime','Thời gian chuyển','giờ'),q('firstBurn','Xung tăng tốc đầu','km/s')],'Δv₁ = √(GM/r₁)(√(2r₂/(r₁+r₂))−1)',s=>{const GM=G*5.972e24,a=s.start*1000,b=s.target*1000,d1=Math.sqrt(GM/a)*(Math.sqrt(2*b/(a+b))-1),d2=Math.sqrt(GM/b)*(1-Math.sqrt(2*a/(a+b)));return {deltaV:(d1+d2)/1000,firstBurn:d1/1000,transferTime:pi*Math.sqrt(((a+b)/2)**3/GM)/3600};},'Vì sao cần hai xung tăng tốc để vào quỹ đạo tròn cao hơn?',{grade:10,view:'transfer',limit:'Hai quỹ đạo tròn đồng phẳng; hai xung tức thời, không lực cản, chỉ chuyển lên quỹ đạo cao hơn.'});
add('tidal_gradient','Chênh lệch hấp dẫn và thủy triều','Cơ học','orbit',[p('distance','Khoảng cách tới thiên thể gây triều',2,10,3.84,'10⁸ m',.1),p('halfSize','Nửa kích thước vật khảo sát',1,10,6.371,'10⁶ m',.1)],[q('near','Gia tốc tương đối phía gần','µm/s²'),q('far','Gia tốc tương đối phía xa','µm/s²'),q('linear','Độ lớn gần đúng','µm/s²')],'Δg gần ≈ 2GM·L/d³',s=>{const d=s.distance*1e8,L=s.halfSize*1e6,GM=G*7.342e22;return {near:(GM/(d-L)**2-GM/d**2)*1e6,far:(GM/(d+L)**2-GM/d**2)*1e6,linear:2*GM*L/d**3*1e6};},'Cả hai phía có thể rời xa tâm tương đối dù lực hấp dẫn đều hướng về thiên thể gây triều?',{grade:10,view:'tidal',limit:'Trường do thiên thể 7,342×10²² kg; trừ gia tốc tại tâm vật; không mô hình hóa thủy động lực đại dương.'});
// 06. Fluid transport and surface effects.
add('venturi','Ống Venturi và áp kế vi sai','Chất lưu','fluid',[p('ratio','Tiết diện lớn / nhỏ',1,4,2,'',.1),p('speed','Tốc độ ở đoạn lớn',.1,3,1,'m/s',.1)],[q('pressureDrop','Chênh áp đoạn lớn trừ nhỏ','kPa'),q('neckSpeed','Tốc độ tại cổ','m/s'),q('head','Chênh cột nước tương đương','m')],'S₁v₁=S₂v₂; p₁−p₂=ρ(v₂²−v₁²)/2',s=>({pressureDrop:.5*s.speed**2*(s.ratio**2-1),neckSpeed:s.speed*s.ratio,head:s.speed**2*(s.ratio**2-1)/(2*g)}),'Tại sao đoạn ống hẹp có áp suất tĩnh nhỏ hơn?',{grade:10,view:'venturi',limit:'Dòng nước ổn định, không nhớt, hai tiết diện cùng độ cao; ρ=1000 kg/m³.'});
add('siphon','Xi-phông và áp suất tại đỉnh','Chất lưu','fluid',[p('top','Đỉnh ống cao hơn mặt thoáng',.1,5,1,'m',.1),p('drop','Đầu ra thấp hơn mặt thoáng',.1,3,1,'m',.1)],[q('pressure','Áp suất tuyệt đối tại đỉnh','kPa'),q('speed','Tốc độ dòng','m/s'),q('margin','Áp suất trên áp suất hơi','kPa')],'v = √(2gH); pđỉnh = pkhí quyển − ρg(h+H)',s=>({pressure:101.325-g*(s.top+s.drop),speed:Math.sqrt(2*g*s.drop),margin:101.325-g*(s.top+s.drop)-2.34}),'Nâng đỉnh ống trong khi giữ độ chênh đầu ra làm áp suất đỉnh thay đổi thế nào?',{grade:10,view:'siphon',limit:'Ống đã mồi đầy nước ở 20 °C, tiết diện đều, bỏ tổn hao; áp suất hơi nước 2,34 kPa; không mô hình tạo bọt hay đứt cột nước.'});
add('poiseuille','Dòng tầng trong ống mao quản','Chất lưu','fluid',[p('radius','Bán kính ống',.1,.8,.3,'mm',.02),p('pressure','Chênh áp hai đầu',10,100,30,'Pa',5),p('viscosity','Độ nhớt động lực',1,10,2,'mPa·s',.2),length()],[q('flow','Lưu lượng','µL/s'),q('centerSpeed','Tốc độ tại tâm','mm/s'),q('reynolds','Số Reynolds')],'Q = πr⁴Δp/(8ηl); v(r)=Δp(a²−r²)/(4ηl)',s=>{const a=s.radius/1000,eta=s.viscosity/1000,Q=pi*a**4*s.pressure/(8*eta*s.length),v=Q/(pi*a*a);return {flow:Q*1e9,centerSpeed:2*v*1000,reynolds:1000*v*2*a/eta};},'Tăng gấp đôi bán kính có làm lưu lượng chỉ tăng gấp đôi không?',{view:'capillary',limit:'Chất lỏng Newton không nén được, dòng tầng đã phát triển; không xét hiệu ứng đầu ống; ρ=1000 kg/m³.'});
add('stokes_settling','Bi nhỏ lắng trong chất lỏng nhớt','Chất lưu','fluid',[p('radius','Bán kính bi',.02,.15,.05,'mm',.01),p('viscosity','Độ nhớt chất lỏng',10,100,50,'mPa·s',2),p('density','Khối lượng riêng bi',1500,8000,2500,'kg/m³',100)],[q('terminal','Tốc độ lắng giới hạn','mm/s'),q('reynolds','Số Reynolds'),q('buoyancy','Lực đẩy','µN',4)],'vgiới hạn = 2(ρbi−ρlỏng)gr²/(9η)',s=>{const a=s.radius/1000,eta=s.viscosity/1000,v=2*(s.density-1000)*g*a*a/(9*eta);const reynolds=1000*v*2*a/eta;return {terminal:reynolds<=.1?v*1000:null,reynolds,buoyancy:1000*g*4*pi*a**3/3*1e6};},'Lực cản cân bằng trọng lực hay phần trọng lực còn lại sau lực đẩy?',{view:'settling',limit:'Bi cầu cô lập, chất lỏng 1000 kg/m³; chỉ xuất tốc độ Stokes khi Reynolds thử ≤ 0,1; Reynolds ngoài miền dùng để chẩn đoán, không phải nghiệm dòng chảy thực; không gần thành bình.'});
add('capillary_rise','Dâng mao dẫn và góc tiếp xúc','Chất lưu','fluid',[p('radius','Bán kính mao quản',.1,2,.5,'mm',.05),p('angle','Góc tiếp xúc',0,140,30,'°',2),p('tension','Sức căng bề mặt',.02,.08,.072,'N/m',.002,3)],[q('height','Độ dâng có dấu','mm'),q('pressure','Chênh áp Laplace','Pa'),q('cosine','Cosin góc tiếp xúc')],'h = 2σ cosθ/(ρgr)',s=>({height:2*s.tension*Math.cos(rad(s.angle))/(1000*g*s.radius/1000)*1000,pressure:2*s.tension*Math.cos(rad(s.angle))/(s.radius/1000),cosine:Math.cos(rad(s.angle))}),'Khi góc tiếp xúc lớn hơn 90°, mặt chất lỏng dâng lên hay hạ xuống?',{grade:10,view:'meniscus',limit:'Ống tròn nhỏ, mặt khum cân bằng, chất lỏng 1000 kg/m³; bỏ qua khối lượng mặt khum.'});
// 07. Other oscillating systems.
add('coupled_pendulums','Hai dao động ghép và trao đổi năng lượng','Dao động','oscillators',[p('coupling','Độ cứng liên kết',1,30,8,'N/m',1),p('stiffness','Độ cứng mỗi lò xo',10,60,20,'N/m',2),mass()],[q('x1','Li độ vật 1','m',4),q('x2','Li độ vật 2','m',4),q('energy','Tổng cơ năng hệ','J',4)],'ω₊²=k/m; ω₋²=(k+2kc)/m',s=>{const w=Math.sqrt(s.stiffness/s.mass),v=Math.sqrt((s.stiffness+2*s.coupling)/s.mass),x1=.05*(Math.cos(w*s.t)+Math.cos(v*s.t)),x2=.05*(Math.cos(w*s.t)-Math.cos(v*s.t)),v1=-.05*(w*Math.sin(w*s.t)+v*Math.sin(v*s.t)),v2=-.05*(w*Math.sin(w*s.t)-v*Math.sin(v*s.t));return {x1,x2,energy:.5*s.mass*(v1*v1+v2*v2)+.5*s.stiffness*(x1*x1+x2*x2)+.5*s.coupling*(x1-x2)**2};},'Vật 2 có thể nhận năng lượng dù ban đầu đứng yên ở vị trí cân bằng không?',{time:true,view:'coupled',limit:'Hai khối bằng nhau, lò xo tuyến tính, ban đầu x₁=0,1 m, x₂=0 và hai vận tốc bằng 0; không ma sát.'});
function largePeriod(a,L){const kk=Math.sin(a/2)**2,n=128,step=pi/(2*n);let sum=0;for(let i=0;i<=n;i++)sum+=(i===0||i===n?1:i%2?4:2)/Math.sqrt(1-kk*Math.sin(i*step)**2);return 4*Math.sqrt(L/g)*sum*step/3;}
add('large_pendulum','Con lắc đơn biên độ lớn','Dao động','oscillators',[p('amplitude','Biên độ góc',5,120,60,'°',5),length()],[q('period','Chu kì phi tuyến','s'),q('smallPeriod','Chu kì gần đúng góc nhỏ','s'),q('deviation','Độ tăng chu kì','%')],'T = 4√(l/g) K(sin²(θ₀/2))',s=>{const period=largePeriod(rad(s.amplitude),s.length),smallPeriod=2*pi*Math.sqrt(s.length/g),[theta,angularSpeed]=integrate(s.t,[rad(s.amplitude),0],(_,y)=>[y[1],-g/s.length*Math.sin(y[0])]);return {period,smallPeriod,deviation:100*(period/smallPeriod-1),theta,angularSpeed};},'Công thức góc nhỏ sai lệch tăng thế nào khi biên độ tăng?',{time:true,duration:(s,d)=>2*d.period,view:'pendulum',limit:'Giải θ̈=−(g/l)sinθ; chu kì bằng tích phân elliptic tính Simpson; bỏ cản, không dùng cosin để giả dao động góc lớn.'});
add('physical_pendulum','Con lắc vật lí: chọn điểm treo','Dao động','oscillators',[p('pivot','Khoảng cách điểm treo tới trọng tâm',.05,.6,.25,'m',.01),length()],[q('period','Chu kì','s'),q('equivalent','Chiều dài tương đương','m'),q('frequency','Tần số','Hz')],'T = 2π√((l²/12+d²)/(gd))',s=>{const equivalent=(s.length*s.length/12+s.pivot**2)/s.pivot;return {equivalent,period:2*pi*Math.sqrt(equivalent/g),frequency:Math.sqrt(g/equivalent)/(2*pi)};},'Điểm treo gần trọng tâm có luôn làm chu kì nhỏ hơn không?',{view:'physical',limit:'Thanh mảnh đồng chất, điểm treo cách trọng tâm d; có thể treo qua giá cứng ngoài thanh; dao động góc nhỏ.'});
add('torsion_pendulum','Con lắc xoắn','Dao động','oscillators',[p('torsion','Hệ số mômen xoắn',.02,1,.2,'N·m/rad',.02),p('inertia','Mômen quán tính',.01,.2,.05,'kg·m²',.01)],[q('angle','Li độ góc','rad'),q('period','Chu kì','s'),q('energy','Cơ năng','J',4)],'Iθ̈+κθ=0; T=2π√(I/κ)',s=>({angle:.3*Math.cos(Math.sqrt(s.torsion/s.inertia)*s.t),period:2*pi*Math.sqrt(s.inertia/s.torsion),energy:.5*s.torsion*.3**2}),'Vì sao tăng mômen quán tính làm dao động xoắn chậm hơn?',{time:true,view:'torsion',limit:'Mômen hồi phục tuyến tính theo góc, biên độ 0,3 rad, không cản.'});
add('u_tube_oscillation','Dao động cột lỏng trong ống chữ U','Dao động','oscillators',[p('liquidLength','Tổng chiều dài cột lỏng',.2,2,1,'m',.05),p('amplitude','Biên độ mỗi mặt thoáng',.005,.05,.02,'m',.005,3)],[q('displacement','Li độ mặt thoáng trái','m',4),q('period','Chu kì','s'),q('difference','Chênh cao hai mặt thoáng','m',4)],'ẍ=−2gx/L; T=2π√(L/(2g))',s=>{const period=2*pi*Math.sqrt(s.liquidLength/(2*g)),displacement=s.amplitude*Math.cos(2*pi*s.t/period);return {period,displacement,difference:2*displacement};},'Vì sao chênh lệch hai mặt thoáng bằng hai lần li độ mỗi bên?',{time:true,view:'utube',limit:'Ống tiết diện đều, chất lỏng không nén được, hai mặt thoáng còn trong nhánh thẳng; không nhớt.'});
// 08. Driven and nonlinear systems use their own equations.
add('vibration_absorber','Bộ hấp thụ rung hai bậc tự do','Dao động','oscillators',[p('frequency','Tần số lực kích thích',.1,2,1,'Hz',.05),p('absorberMass','Khối lượng phụ',.1,1,.3,'kg',.05),p('coupling','Độ cứng lò xo phụ',1,30,12,'N/m',1)],[q('amplitude1','Biên độ vật chính','m',4),q('amplitude2','Biên độ vật phụ','m',4),q('ratio','Biên độ chính / hệ không có phụ')],'Hệ phức: (k₁+k₂−m₁ω²+iω(c₁+c₂))X₁−(k₂+iωc₂)X₂=F',s=>{const w=2*pi*s.frequency,a=40+s.coupling-w*w,b=.6*w,d=s.coupling-s.absorberMass*w*w,e=.1*w,cr=s.coupling,ci=.1*w,dr=a*d-b*e-cr*cr+ci*ci,di=a*e+b*d-2*cr*ci,den=Math.hypot(dr,di),amplitude1=Math.hypot(d,e)/den,amplitude2=Math.hypot(cr,ci)/den;return {amplitude1,amplitude2,ratio:amplitude1*Math.hypot(40-w*w,.5*w)};},'Bổ sung một khối phụ có thể giảm rung của khối chính ở một miền tần số không?',{view:'absorber',limit:'Trạng thái ổn định hình sin; m₁=1 kg, k₁=40 N/m, c₁=0,5 N·s/m, c₂=0,1 N·s/m, lực biên độ 1 N.'});
add('base_isolation','Cách rung khi đế dao động','Dao động','oscillators',[p('ratio','Tần số kích thích / tần số riêng',.1,4,2,'',.05),p('damping','Tỉ số cản',.03,.8,.2,'',.01)],[q('transmissibility','Tỉ số biên độ vật / đế'),q('phase','Pha chậm của vật so với đế','°'),q('relative','Biên độ tương đối / đế')],'|X/Y| = √((1+(2ζr)²)/((1−r²)²+(2ζr)²))',s=>{const a=1-s.ratio**2,b=2*s.damping*s.ratio,den=Math.hypot(a,b);return {transmissibility:Math.hypot(1,b)/den,phase:deg(Math.atan2(b,a)-Math.atan2(b,1)),relative:s.ratio**2/den};},'Cản lớn có luôn làm khả năng cách rung tốt hơn ở mọi tần số không?',{view:'isolation',limit:'Hệ một bậc tự do tuyến tính, đế chuyển động hình sin; kết quả là đáp ứng ổn định, không xét quá độ.'});
add('parametric_oscillation','Kích thích tham số bằng độ cứng biến thiên','Dao động','oscillators',[p('modulation','Độ sâu biến thiên độ cứng',0,.4,.2,'',.02),p('ratio','Tần số biến thiên / tần số riêng',.5,3,2,'',.05)],[q('x','Li độ','m',4),q('energy','Năng lượng theo độ cứng tức thời','J',4),q('stiffness','Độ cứng tức thời','N/m')],'ẍ+2ζω₀ẋ+ω₀²(1+ε cosΩt)x=0',s=>{const w=2*pi,[x,v]=integrate(s.t,[.05,0],(t,y)=>[y[1],-.06*w*y[1]-w*w*(1+s.modulation*Math.cos(s.ratio*w*t))*y[0]],.008),stiffness=w*w*(1+s.modulation*Math.cos(s.ratio*w*s.t));return {x,v,stiffness,energy:.5*v*v+.5*stiffness*x*x};},'Hệ nhận năng lượng bằng cách thay đổi tham số nào khi không có lực cộng trực tiếp?',{time:true,view:'parametric',limit:'m=1 kg, f₀=1 Hz, ζ=0,03; giải RK4, độ cứng được bộ kích thích ngoài điều khiển; cơ năng không bảo toàn.'});
add('duffing','Lò xo phi tuyến Duffing','Dao động','oscillators',[p('cubic','Hệ số đàn hồi bậc ba',0,40,15,'N/m³',2),p('frequency','Tần số lực',.2,1.5,.8,'Hz',.05),p('force','Biên độ lực cưỡng bức',.1,2,.5,'N',.1)],[q('x','Li độ','m',4),q('v','Vận tốc','m/s',4),q('elastic','Lực đàn hồi có dấu','N')],'ẍ+0,4ẋ+16x+αx³=F cos(2πft)',s=>{const [x,v]=integrate(s.t,[.05,0],(t,y)=>[y[1],s.force*Math.cos(2*pi*s.frequency*t)-.4*y[1]-16*y[0]-s.cubic*y[0]**3],.01);return {x,v,elastic:-16*x-s.cubic*x**3};},'Quan hệ lực–li độ còn là đường thẳng khi hệ số bậc ba khác 0 không?',{time:true,view:'duffing',limit:'m=1 kg, k=16 N/m, c=0,4 N·s/m; đàn hồi cứng dần α≥0; nghiệm RK4 từ trạng thái đầu đã nêu.'});
add('van_der_pol','Tự dao động Van der Pol','Dao động','oscillators',[p('gain','Hệ số tự kích',.1,1.5,.5,'s⁻¹',.1),p('initial','Li độ ban đầu',.1,2,.3,'m',.1)],[q('x','Li độ','m',4),q('v','Vận tốc','m/s',4),q('power','Công suất bơm năng lượng có dấu','W')],'ẍ − µ(1−x²)ẋ + 4x = 0',s=>{const [x,v]=integrate(s.t,[s.initial,0],(_,y)=>[y[1],s.gain*(1-y[0]*y[0])*y[1]-4*y[0]],.008);return {x,v,power:s.gain*(1-x*x)*v*v};},'Vì sao hệ có thể bơm năng lượng lúc biên độ nhỏ và lấy năng lượng ra lúc biên độ lớn?',{time:true,window:15,view:'active',limit:'Mô hình tự kích có nguồn năng lượng ngoài, m=1 kg; x được chuẩn hóa theo 1 m; không phải dao động tự do bảo toàn cơ năng.'});
// 09. Boundary waves, wave energy and dispersion.
add('string_boundary','Phản xạ và truyền sóng qua mối nối dây','Sóng','wave_boundary',[p('density2','Mật độ dài dây thứ hai',1,20,8,'g/m',.5),p('density1','Mật độ dài dây thứ nhất',1,20,2,'g/m',.5),p('tension','Lực căng chung',1,30,10,'N',1)],[q('reflection','Hệ số phản xạ li độ'),q('reflectedPower','Phần công suất phản xạ'),q('transmittedPower','Phần công suất truyền')],'r=(Z₁−Z₂)/(Z₁+Z₂); R=r²; T=4Z₁Z₂/(Z₁+Z₂)²',s=>{const z1=Math.sqrt(s.tension*s.density1/1000),z2=Math.sqrt(s.tension*s.density2/1000),reflection=(z1-z2)/(z1+z2);return {reflection,reflectedPower:reflection**2,transmittedPower:4*z1*z2/(z1+z2)**2,amplitudeT:2*z1/(z1+z2),speed1:Math.sqrt(1000*s.tension/s.density1),speed2:Math.sqrt(1000*s.tension/s.density2)};},'Khi nào sóng phản xạ đổi dấu và tổng hai phần công suất bằng bao nhiêu?',{view:'junction',limit:'Hai dây bán vô hạn, nối không khối lượng, cùng lực căng, sóng ngang biên độ nhỏ; không hao phí.'});
add('bead_scattering','Sóng tán xạ tại hạt nặng trên dây','Sóng','wave_boundary',[p('mass','Khối lượng hạt',.01,.2,.05,'kg',.01),p('frequency','Tần số sóng',1,20,5,'Hz',.5),p('impedance','Trở kháng mỗi dây',.1,3,1,'kg/s',.1)],[q('reflectedPower','Phần công suất phản xạ'),q('transmittedPower','Phần công suất truyền'),q('phase','Pha sóng phản xạ','°')],'R=(mω)²/(4Z²+(mω)²); T=1−R',s=>{const a=2*pi*s.frequency*s.mass,den=4*s.impedance**2+a*a;return {reflectedPower:a*a/den,transmittedPower:4*s.impedance**2/den,phase:deg(Math.atan2(2*a*s.impedance,-a*a)),reflection:-a*a/den,amplitudeT:2*s.impedance/Math.sqrt(den)};},'Hạt nặng phản xạ mạnh hơn với sóng có tần số cao hay thấp?',{view:'bead',limit:'Hạt điểm nối hai dây giống nhau, dao động nhỏ, không cản; trở kháng Z=√(Tµ) được nhập trực tiếp.'});
add('water_refraction','Khúc xạ sóng nước nông','Sóng','wave_boundary',[p('angle','Góc tới',0,70,30,'°',1),p('depth1','Độ sâu vùng tới',.01,.1,.04,'m',.005,3),p('depth2','Độ sâu vùng sau',.01,.1,.02,'m',.005,3)],[q('angle2','Góc khúc xạ','°'),q('speed1','Tốc độ vùng tới','m/s'),q('speed2','Tốc độ vùng sau','m/s')],'v=√(gh); sinθ₁/v₁=sinθ₂/v₂',s=>{const speed1=Math.sqrt(g*s.depth1),speed2=Math.sqrt(g*s.depth2),u=Math.sin(rad(s.angle))*speed2/speed1;return {speed1,speed2,angle2:Math.abs(u)<=1?deg(Math.asin(u)):null,allowed:Math.abs(u)<=1?1:0};},'Sóng đi vào vùng nông hơn lệch gần hay xa pháp tuyến?',{view:'water',limit:'Sóng tuyến tính nước nông với bước sóng rất lớn so với độ sâu; nếu không có góc truyền thực, chỉ hiển thị giới hạn mô hình.'});
add('string_power','Công suất sóng trên dây theo biên độ','Sóng','wave_boundary',[p('amplitude','Biên độ sóng',1,10,4,'mm',.5),p('frequency','Tần số',5,50,20,'Hz',1),p('density','Mật độ dài',1,10,2,'g/m',.5),p('tension','Lực căng',1,30,10,'N',1)],[q('power','Công suất trung bình','mW'),q('speed','Tốc độ truyền','m/s'),q('wavelength','Bước sóng','m')],'P̄=½µω²A²v; v=√(T/µ)',s=>{const density=s.density/1000,speed=Math.sqrt(s.tension/density);return {speed,power:.5*density*(2*pi*s.frequency)**2*(s.amplitude/1000)**2*speed*1000,wavelength:speed/s.frequency};},'Biên độ tăng hai lần làm công suất truyền tăng bao nhiêu lần?',{extra:false,view:'power',limit:'Sóng hình sin trên dây dài, biên độ và độ dốc nhỏ; công suất lấy trung bình theo chu kì.'});
add('dispersive_packet','Vận tốc nhóm của sóng nước','Sóng','wave_boundary',[p('wavelength','Bước sóng trung tâm',.1,5,1,'m',.1),p('depth','Độ sâu nước',.02,2,.2,'m',.02)],[q('group','Vận tốc nhóm','m/s'),q('phase','Vận tốc pha','m/s'),q('ratio','Vận tốc nhóm / pha')],'ω²=gk tanh(kh); vg=vp[1+2kh/sinh(2kh)]/2',s=>{const kk=2*pi/s.wavelength,z=kk*s.depth,phase=Math.sqrt(g*Math.tanh(z)/kk),ratio=.5*(1+2*z/Math.sinh(2*z));return {phase,group:phase*ratio,ratio};},'Trong nước sâu, đỉnh sóng và bao sóng có truyền cùng vận tốc không?',{view:'packet',limit:'Sóng trọng lực tuyến tính trên nước, bỏ sức căng bề mặt; vận tốc nhóm áp dụng cho bó sóng hẹp về phổ.'});
// 10. Acoustic instruments and propagation.
add('helmholtz','Cộng hưởng Helmholtz của bình có cổ','Sóng','acoustic',[p('volume','Thể tích khoang',.2,5,1,'L',.1),p('radius','Bán kính cổ',.5,2,1,'cm',.1),p('neck','Chiều dài cổ',1,10,3,'cm',.5)],[q('frequency','Tần số cộng hưởng','Hz'),q('effective','Chiều dài cổ hiệu dụng','cm'),q('area','Tiết diện cổ','cm²')],'f = c/(2π) √(S/(VLeff)); Leff=L+1,7r',s=>({frequency:343/(2*pi)*Math.sqrt(pi*(s.radius/100)**2/(s.volume/1000*(s.neck+1.7*s.radius)/100)),effective:s.neck+1.7*s.radius,area:pi*s.radius*s.radius}),'Tăng thể tích bình làm âm cộng hưởng trầm hơn vì sao?',{view:'bottle',limit:'Khoang nhỏ so với bước sóng, cổ tròn, c=343 m/s; hiệu chỉnh hai đầu cổ xấp xỉ 1,7r, bỏ cản nhớt.'});
add('harmonic_timbre','Tổng hợp họa âm tạo âm sắc','Sóng','acoustic',[p('phase','Pha của âm cơ bản',0,360,60,'°',5),p('second','Biên độ họa âm 2',0,1,.4,'',.05),p('third','Biên độ họa âm 3',0,1,.2,'',.05)],[q('signal','Dạng sóng tức thời'),q('rms','Giá trị căn quân phương'),q('fundamental','Tần số cơ bản','Hz',0)],'y=sinφ+a₂sin2φ+a₃sin3φ',s=>({signal:Math.sin(rad(s.phase))+s.second*Math.sin(2*rad(s.phase))+s.third*Math.sin(3*rad(s.phase)),rms:Math.sqrt((1+s.second**2+s.third**2)/2),fundamental:220}), 'Cùng tần số cơ bản nhưng khác thành phần họa âm làm dạng sóng thay đổi thế nào?',{view:'timbre',limit:'Tổng ba thành phần đồng pha ban đầu, biên độ chuẩn hóa; hình biểu diễn pha, không phải chuyển vị không khí theo đường sin trong không gian.'});
add('room_reverberation','Thời gian vang và hấp thụ âm','Sóng','acoustic',[p('absorption','Hệ số hấp thụ trung bình',.05,.8,.2,'',.01),p('volume','Thể tích phòng',20,300,100,'m³',10),p('surface','Tổng diện tích bề mặt',50,300,150,'m²',10)],[q('reverb','Thời gian vang T60','s'),q('equivalent','Diện tích hấp thụ tương đương','m²'),q('decay','Độ giảm mức âm mỗi giây','dB/s')],'T60 ≈ 0,161 V/(αS)',s=>{const equivalent=s.absorption*s.surface,reverb=.161*s.volume/equivalent;return {reverb,equivalent,decay:60/reverb};},'Vật liệu hấp thụ âm làm giảm thời gian vang mà không nhất thiết đổi kích thước phòng ra sao?',{view:'room',limit:'Công thức Sabine gần đúng cho trường âm khuếch tán; không tính từng phản xạ hay tư vấn xử lí âm học công trình.'});
add('sound_tdoa','Định vị âm bằng chênh lệch thời gian tới','Sóng','acoustic',[p('x','Hoành độ nguồn',-3,3,1,'m',.1),p('y','Khoảng cách ngang tới dãy đầu thu',.5,4,2,'m',.1),p('baseline','Khoảng cách hai đầu thu',.5,4,2,'m',.1)],[q('delay','Thời gian tới trái trừ phải','ms'),q('leftDistance','Khoảng cách tới đầu trái','m'),q('rightDistance','Khoảng cách tới đầu phải','m')],'Δt=(rtrái−rphải)/c',s=>{const leftDistance=Math.hypot(s.x+s.baseline/2,s.y),rightDistance=Math.hypot(s.x-s.baseline/2,s.y);return {leftDistance,rightDistance,delay:(leftDistance-rightDistance)/343*1000};},'Hai đầu thu có xác định duy nhất một vị trí nguồn âm trong mặt phẳng không?',{view:'microphones',limit:'Không khí đồng nhất, c=343 m/s; bỏ phản xạ và nhiễu. Một chênh thời gian ứng với nhiều vị trí trên đường hyperbol.'});
add('mach_cone','Nón Mach của nguồn siêu thanh','Sóng','acoustic',[p('mach','Số Mach',1.1,3,1.5,'',.1),p('soundSpeed','Tốc độ âm môi trường',300,360,343,'m/s',5)],[q('angle','Nửa góc nón Mach','°'),q('speed','Tốc độ nguồn','m/s'),q('ratio','Sin góc nón')],'sinµ=1/M; M=vnguồn/c',s=>({angle:deg(Math.asin(1/s.mach)),speed:s.mach*s.soundSpeed,ratio:1/s.mach}),'Nguồn nhanh hơn làm nón Mach mở rộng hay hẹp đi?',{view:'mach',limit:'Nguồn điểm chuyển động đều nhanh hơn âm trong môi trường đồng nhất; sơ đồ mặt sóng, không mô hình cường độ sóng xung kích.'});
// 11. Continuous charge distributions, not point-charge substitutions.
add('charged_ring','Điện trường trên trục vòng tích điện','Điện trường','field_geometry',[p('distance','Tọa độ trên trục',-.8,.8,.2,'m',.02),p('radius','Bán kính vòng',.1,.5,.2,'m',.01),p('charge','Điện tích vòng',-5,5,2,'nC',.2)],[q('field','Điện trường dọc trục','N/C'),q('potential','Điện thế','V'),q('maximumAt','Tọa độ cực đại |E| phía dương','m')],'Ez=kQz/(z²+a²)³ᐟ²',s=>({field:k*s.charge*1e-9*s.distance/(s.distance**2+s.radius**2)**1.5,potential:k*s.charge*1e-9/Math.hypot(s.distance,s.radius),maximumAt:s.radius/Math.SQRT2}),'Tại tâm vòng, điện trường bằng 0 có đồng nghĩa điện thế bằng 0 không?',{view:'ring',limit:'Vòng mảnh tích điện đều; gốc điện thế ở vô cực, khảo sát đúng trên trục đối xứng.'});
add('charged_rod','Trường trên đường trung trực thanh tích điện','Điện trường','field_geometry',[p('distance','Khoảng cách tới tâm thanh',.05,1,.3,'m',.02),length(),p('charge','Điện tích toàn thanh',-5,5,2,'nC',.2)],[q('field','Điện trường vuông góc thanh','N/C'),q('potential','Điện thế','V'),q('pointApprox','Trường nếu coi điện tích điểm','N/C')],'E=kQ/[r√(r²+(L/2)²)]',s=>({field:k*s.charge*1e-9/(s.distance*Math.hypot(s.distance,s.length/2)),potential:2*k*s.charge*1e-9/s.length*Math.asinh(s.length/(2*s.distance)),pointApprox:k*s.charge*1e-9/s.distance**2}),'Ở xa thanh, mô hình điện tích điểm gần đúng tốt hơn như thế nào?',{view:'rod',limit:'Thanh mảnh, phân bố điện tích đều, đầu dò trên đường trung trực; gốc điện thế vô cực.'});
add('charged_disk','Điện trường trên trục đĩa tích điện','Điện trường','field_geometry',[p('distance','Khoảng cách từ mặt đĩa',.01,1,.2,'m',.01),p('radius','Bán kính đĩa',.1,1,.4,'m',.02),p('density','Mật độ điện mặt',.01,.2,.05,'µC/m²',.01)],[q('field','Điện trường dọc trục','N/C'),q('potential','Điện thế','V'),q('planeApprox','Trường mặt phẳng vô hạn','N/C')],'E=σ(1−z/√(z²+a²))/(2ε₀)',s=>{const f=s.density*1e-6/(2*eps);return {field:f*(1-s.distance/Math.hypot(s.distance,s.radius)),potential:f*(Math.hypot(s.distance,s.radius)-s.distance),planeApprox:f};},'Gần tâm đĩa lớn, điện trường tiến gần mô hình mặt phẳng như thế nào?',{view:'disk',limit:'Đĩa mỏng tích điện đều, khảo sát phía z>0 trên trục; bỏ tái phân bố điện tích của vật dẫn thực.'});
add('charged_solid_sphere','Bên trong quả cầu cách điện tích điện đều','Điện trường','field_geometry',[p('distance','Khoảng cách từ tâm',0,1.5,.2,'m',.02),p('radius','Bán kính cầu',.2,.8,.5,'m',.02),p('charge','Điện tích cầu',-5,5,2,'nC',.2)],[q('field','Điện trường theo bán kính','N/C'),q('potential','Điện thế','V'),q('enclosed','Điện tích trong mặt Gauss','nC')],'Etrong=kQr/R³; Vtrong=kQ(3−r²/R²)/(2R)',s=>{const inside=s.distance<=s.radius,Q=s.charge*1e-9;return {field:inside?k*Q*s.distance/s.radius**3:k*Q/s.distance**2,potential:inside?k*Q/(2*s.radius)*(3-s.distance**2/s.radius**2):k*Q/s.distance,enclosed:inside?s.charge*(s.distance/s.radius)**3:s.charge};},'Vì sao không được dùng kQ/r² với toàn bộ Q ở bên trong quả cầu cách điện?',{view:'sphere',limit:'Mật độ điện thể tích đồng đều; quả cầu cách điện, khác với quả cầu dẫn cân bằng tĩnh điện.'});
add('charged_plane','Bước nhảy điện trường qua mặt phẳng điện','Điện trường','field_geometry',[p('position','Tọa độ có dấu qua mặt phẳng',-1,1,.3,'m',.05),p('density','Mật độ điện mặt có dấu',-.1,.1,.03,'µC/m²',.01)],[q('field','Điện trường có dấu','N/C'),q('jump','Bước nhảy E phải trừ trái','N/C'),q('magnitude','Độ lớn mỗi phía','N/C')],'Ephải−Etrái=σ/ε₀',s=>({field:s.position===0?null:Math.sign(s.position)*s.density*1e-6/(2*eps),jump:s.density*1e-6/eps,magnitude:Math.abs(s.density)*1e-6/(2*eps)}),'Trường đổi chiều khi đi qua mặt tích điện, còn độ lớn phụ thuộc khoảng cách không?',{view:'plane',limit:'Mặt phẳng vô hạn không dẫn, tích điện đều; ngay trên lớp điện lí tưởng, điện trường không được gán một giá trị duy nhất.'});
// 12. Potential and assembly energy.
add('electric_turning','Điểm quay đầu trong lực đẩy điện','Điện trường','potential',[p('speed','Tốc độ ban đầu hướng về nguồn',.1,3,1,'m/s',.1),p('charge','Điện tích nguồn dương',.1,5,2,'nC',.1),p('initial','Khoảng cách ban đầu',.1,1,.5,'m',.02)],[q('turning','Khoảng cách gần nhất','m',4),q('kinetic','Động năng ban đầu','µJ'),q('energy','Tổng năng lượng','µJ')],'kQq/rmin=kQq/r₀+mv₀²/2',s=>{const U=k*s.charge*1e-18/s.initial,K=.5*1e-6*s.speed**2;return {turning:k*s.charge*1e-18/(U+K),kinetic:K*1e6,energy:(U+K)*1e6};},'Vật dương có thể chạm nguồn điện tích điểm dương khi tổng năng lượng hữu hạn không?',{view:'turning',limit:'Điện tích thử +1 nC, khối lượng 1 mg; nguồn cố định, chuyển động hướng tâm, không bức xạ; hình mô tả hai trạng thái đầu và quay đầu.'});
add('equipotential_map','Bản đồ điện thế và hướng điện trường','Điện trường','potential',[p('x','Hoành độ đầu dò',-2,2,.4,'m',.1),p('y','Tung độ đầu dò',.1,2,.6,'m',.1),p('charge','Độ lớn hai điện tích trái dấu',.5,5,2,'nC',.1)],[q('potential','Điện thế đầu dò','V'),q('ex','Điện trường theo x','N/C'),q('ey','Điện trường theo y','N/C')],'V=kQ(1/r₊−1/r₋); E=−grad V',s=>{const a=s.x+.6,b=s.x-.6,r1=Math.hypot(a,s.y),r2=Math.hypot(b,s.y),Q=k*s.charge*1e-9;return {potential:Q*(1/r1-1/r2),ex:Q*(a/r1**3-b/r2**3),ey:Q*s.y*(1/r1**3-1/r2**3)};},'Điện thế bằng 0 trên trung trực có đồng nghĩa vectơ điện trường bằng 0 không?',{view:'map',limit:'Hai nguồn điểm cố định ở (−0,6;0) và (0,6;0) m; khảo sát tránh điểm nguồn; lưới màu chỉ biểu diễn giá trị điện thế.'});
add('three_charge_energy','Năng lượng lắp ráp ba điện tích','Điện trường','potential',[p('third','Điện tích thứ ba',-4,4,-1,'nC',.2),p('side','Cạnh tam giác đều',.1,1,.4,'m',.02),p('charge','Hai điện tích đầu bằng nhau',.5,4,2,'nC',.2)],[q('energy','Năng lượng toàn hệ','nJ'),q('workThird','Công ngoài đưa điện tích 3 vào','nJ'),q('pairEnergy','Năng lượng cặp ban đầu','nJ')],'U=k(q₁q₂+q₁q₃+q₂q₃)/a',s=>({energy:k*(s.charge**2+2*s.charge*s.third)*1e-9/s.side,workThird:2*k*s.charge*s.third*1e-9/s.side,pairEnergy:k*s.charge**2*1e-9/s.side}),'Công ngoài đưa điện tích thứ ba vào có thể âm trong điều kiện nào?',{extra:false,view:'triangle',limit:'Ba điện tích điểm ở ba đỉnh tam giác đều, đưa vào rất chậm từ vô cực; không tính tự năng của từng điện tích điểm.'});
add('electric_work_paths','Công điện trường trên hai đường đi','Điện trường','potential',[p('detour','Độ cao điểm vòng',0,1,.5,'m',.05),p('start','Khoảng cách đầu tới nguồn',.1,.6,.2,'m',.02),p('end','Khoảng cách cuối tới nguồn',.6,1.5,1,'m',.05)],[q('straightWork','Công trên đường thẳng','nJ'),q('detourWork','Công trên đường gấp khúc','nJ'),q('pathLength','Độ dài đường gấp khúc','m')],'A=q(VA−VB), không phụ thuộc đường đi',s=>({straightWork:k*1e-9*(1/s.start-1/s.end),detourWork:k*1e-9*(1/s.start-1/s.end),pathLength:2*Math.hypot((s.end-s.start)/2,s.detour)}),'Đường dài hơn có làm công tĩnh điện lớn hơn khi hai đầu mút giữ nguyên không?',{extra:false,view:'paths',limit:'Nguồn cố định +1 nC, điện tích thử +1 nC; hai đường nằm cùng mặt phẳng và không đi qua nguồn.'});
add('connected_spheres','Hai cầu dẫn nối dây và chia điện tích','Điện trường','potential',[p('radius1','Bán kính cầu 1',1,10,3,'cm',.5),p('radius2','Bán kính cầu 2',1,10,6,'cm',.5),p('charge','Tổng điện tích',-5,5,2,'nC',.2)],[q('charge1','Điện tích cầu 1','nC'),q('charge2','Điện tích cầu 2','nC'),q('potential','Điện thế chung','V')],'q₁/R₁=q₂/R₂; q₁+q₂=Q',s=>({charge1:s.charge*s.radius1/(s.radius1+s.radius2),charge2:s.charge*s.radius2/(s.radius1+s.radius2),potential:k*s.charge*1e-9/((s.radius1+s.radius2)/100)}),'Cân bằng điện thế có đồng nghĩa chia điện tích bằng nhau không?',{view:'spheres',limit:'Hai cầu ở rất xa nhau so với bán kính, dây mảnh có điện dung bỏ qua; kết quả là trạng thái cân bằng cuối.'});
// 13. Conductors and capacitor geometries.
add('conducting_shell','Vỏ cầu dẫn có điện tích trong khoang','Điện trường','capacitor_geometry',[p('distance','Khoảng cách tới tâm',.05,1,.4,'m',.01),p('central','Điện tích tại tâm khoang',-3,3,1,'nC',.2),p('shell','Điện tích thuần của vỏ',-3,3,1,'nC',.2)],[q('field','Điện trường theo bán kính','N/C'),q('potential','Điện thế','V'),q('innerCharge','Điện tích cảm ứng mặt trong','nC')],'E=0 trong phần kim loại; qtrong=−qtâm',s=>{const a=.25,b=.5,z=s.distance,inside=z<a,metal=z>=a&&z<=b;return {field:inside?k*s.central*1e-9/z**2:metal?0:k*(s.central+s.shell)*1e-9/z**2,potential:inside?k*1e-9*(s.central/z-s.central/a+(s.central+s.shell)/b):metal?k*(s.central+s.shell)*1e-9/b:k*(s.central+s.shell)*1e-9/z,innerCharge:-s.central};},'Khoang có điện tích ở tâm có điện trường bằng 0 như phần kim loại không?',{view:'shell',limit:'Vỏ cầu đồng tâm bán kính trong 0,25 m và ngoài 0,5 m; nguồn đúng tại tâm, cân bằng tĩnh điện; trên mặt có thể có bước nhảy trường.'});
add('coaxial_capacitor','Tụ điện đồng trục','Điện trường','capacitor_geometry',[p('outer','Bán kính trụ ngoài',2,10,4,'cm',.2),p('length','Chiều dài hai trụ',.2,2,1,'m',.1),voltage()],[q('capacity','Điện dung','pF'),q('field','Trường tại giữa hai bán kính','V/m'),q('energy','Năng lượng','nJ')],'C=2πε₀L/ln(b/a); E(r)=U/[r ln(b/a)]',s=>{const a=.01,b=s.outer/100,C=2*pi*eps*s.length/Math.log(b/a);return {capacity:C*1e12,field:s.voltage/((a+b)/2*Math.log(b/a)),energy:.5*C*s.voltage**2*1e9};},'Tại cùng hiệu điện thế, trường trong khe có đều theo bán kính không?',{view:'coax',limit:'Trụ trong bán kính 1 cm; bỏ hiệu ứng đầu, môi trường chân không, trụ ngoài luôn lớn hơn trụ trong.'});
add('spherical_capacitor','Tụ điện hai mặt cầu đồng tâm','Điện trường','capacitor_geometry',[p('outer','Bán kính cầu ngoài',.06,.3,.1,'m',.01),p('inner','Bán kính cầu trong',.01,.05,.03,'m',.005,3),voltage()],[q('capacity','Điện dung','pF'),q('charge','Điện tích bản dương','nC'),q('field','Trường sát cầu trong','V/m')],'C=4πε₀ab/(b−a)',s=>{const C=4*pi*eps*s.inner*s.outer/(s.outer-s.inner);return {capacity:C*1e12,charge:C*s.voltage*1e9,field:C*s.voltage/(4*pi*eps*s.inner**2)};},'Khi cầu ngoài ở rất xa, điện dung tiến tới giá trị nào?',{view:'spherical',limit:'Hai cầu đồng tâm trong chân không; bỏ dây nối và lỗ trên bản cầu.'});
add('isolated_dielectric','Chèn điện môi khi tụ đã ngắt nguồn','Điện trường','capacitor_geometry',[p('dielectric','Hằng số điện môi',1,6,3,'',.2),p('capacity','Điện dung ban đầu',10,200,50,'pF',10),p('charge','Điện tích cố định',.1,5,1,'nC',.1)],[q('voltage','Điện áp sau chèn','V'),q('energy','Năng lượng sau chèn','nJ'),q('released','Năng lượng điện trường giảm','nJ')],'Q cố định; U=Q/(κC₀); W=Q²/(2κC₀)',s=>({voltage:1000*s.charge/(s.dielectric*s.capacity),energy:500*s.charge**2/(s.dielectric*s.capacity),released:500*s.charge**2/s.capacity*(1-1/s.dielectric)}),'Kết quả khác với tụ còn nối nguồn ở đại lượng nào được giữ không đổi?',{extra:false,view:'dielectric',limit:'Tụ được ngắt nguồn và cách điện hoàn toàn; điện môi tuyến tính lấp đầy khe, bỏ rò điện; năng lượng giảm có thể chuyển thành công cơ.'});
add('layered_dielectric','Hai lớp điện môi trong khe tụ','Điện trường','capacitor_geometry',[p('fraction','Tỉ phần bề dày lớp 1',.1,.9,.5,'',.05),p('dielectric','Hằng số điện môi lớp 2',1,8,4,'',.2),p('gap','Bề dày toàn khe',.5,5,2,'mm',.1),voltage()],[q('field1','Trường trong lớp 1','V/mm'),q('field2','Trường trong lớp 2','V/mm'),q('capacity','Điện dung tương đương','pF')],'D₁=D₂; U=E₁d₁+E₂d₂',s=>{const a=s.fraction*s.gap/1000,b=(1-s.fraction)*s.gap/1000,E1=s.voltage/(a+2*b/s.dielectric);return {field1:E1/1000,field2:2*E1/s.dielectric/1000,capacity:eps*.01/(a/2+b/s.dielectric)*1e12};},'Điện trường hai lớp có bằng nhau khi không có điện tích tự do trên mặt phân cách không?',{view:'layers',limit:'Lớp 1 có κ₁=2, lớp 2 nhập κ₂; diện tích bản 100 cm², mặt phân cách song song bản; bỏ hiệu ứng mép.'});
// 14. Circuit networks solved by Kirchhoff laws.
add('two_meshes','Hai vòng mạch có nhánh chung','Dòng điện','network',[p('source2','Suất điện động vòng 2',0,12,6,'V',.5),p('r1','Điện trở vòng 1',10,100,30,'Ω',5),p('r2','Điện trở vòng 2',10,100,40,'Ω',5),p('shared','Điện trở nhánh chung',10,100,20,'Ω',5)],[q('current1','Dòng vòng 1','A',4),q('current2','Dòng vòng 2','A',4),q('sharedCurrent','Dòng nhánh chung','A',4)],'(R₁+Rc)I₁−RcI₂=E₁; −RcI₁+(R₂+Rc)I₂=E₂',s=>{const a=s.r1+s.shared,b=s.r2+s.shared,den=a*b-s.shared**2,current1=(12*b+s.shared*s.source2)/den,current2=(a*s.source2+12*s.shared)/den;return {current1,current2,sharedCurrent:current1-current2,power:12*current1+s.source2*current2,loss:current1**2*s.r1+current2**2*s.r2+(current1-current2)**2*s.shared};},'Dòng qua nhánh chung có bằng tổng hai dòng vòng theo quy ước đã chọn không?',{view:'mesh',limit:'E₁=12 V, hai dòng vòng cùng chiều kim đồng hồ; nhánh chung mang I₁−I₂, nguồn lí tưởng.'});
add('star_delta','Biến đổi điện trở sao–tam giác','Dòng điện','network',[p('r1','Nhánh sao a',10,100,30,'Ω',5),p('r2','Nhánh sao b',10,100,40,'Ω',5),p('r3','Nhánh sao c',10,100,50,'Ω',5)],[q('rab','Cạnh tam giác ab','Ω'),q('rbc','Cạnh tam giác bc','Ω'),q('rca','Cạnh tam giác ca','Ω')],'Rab=Ra+Rb+RaRb/Rc',s=>({rab:s.r1+s.r2+s.r1*s.r2/s.r3,rbc:s.r2+s.r3+s.r2*s.r3/s.r1,rca:s.r3+s.r1+s.r3*s.r1/s.r2}),'Kiểm tra điện trở nhìn từ hai cực bất kì khi cực thứ ba hở có giữ nguyên không?',{view:'star',limit:'Ba điện trở dương tuyến tính; tương đương giữa ba đầu nối, không phải nối trực tiếp hai sơ đồ cùng lúc.'});
function ladder(n,rs,rp){let z=Infinity;for(let j=0;j<n;j++)z=rs+1/(1/rp+(Number.isFinite(z)?1/z:0));return z;}
add('resistor_ladder','Mạng thang điện trở hữu hạn','Dòng điện','network',[p('stages','Số tầng',1,6,3,'',1,0),p('series','Điện trở dọc mỗi tầng',10,100,30,'Ω',5),p('shunt','Điện trở ngang mỗi tầng',10,100,50,'Ω',5)],[q('equivalent','Điện trở đầu vào','Ω'),q('inputCurrent','Dòng đầu vào','mA'),q('lastVoltage','Điện áp nút cuối','V')],'Zn=Rs+(Rp∥Zn−1), Z₀=∞',s=>{const n=Math.round(s.stages),equivalent=ladder(n,s.series,s.shunt);let v=12;for(let j=n;j>0;j--){const next=ladder(j-1,s.series,s.shunt),parallel=1/(1/s.shunt+(Number.isFinite(next)?1/next:0));v*=parallel/(s.series+parallel);}return {equivalent,inputCurrent:12000/equivalent,lastVoltage:v};},'Thêm tầng có làm điện trở đầu vào tăng mãi không giới hạn không?',{view:'ladder',discrete:true,limit:'Mỗi tầng gồm một điện trở dọc rồi một điện trở xuống dây chung; nguồn 12 V; số tầng là số nguyên.'});
add('unbalanced_bridge','Cầu điện lệch cân bằng có điện kế','Dòng điện','network',[p('r1','Điện trở trên trái',10,100,30,'Ω',5),p('r2','Điện trở dưới trái',10,100,40,'Ω',5),p('r3','Điện trở trên phải',10,100,50,'Ω',5),p('r4','Điện trở dưới phải',10,100,60,'Ω',5),p('meter','Điện trở điện kế',10,500,100,'Ω',10)],[q('meterCurrent','Dòng điện kế trái sang phải','mA'),q('va','Điện thế nút trái','V'),q('vb','Điện thế nút phải','V')],'Giải định luật nút tại hai đầu điện kế',s=>{const [va,vb]=linear3([[1/s.r1+1/s.r2+1/s.meter,-1/s.meter,0],[-1/s.meter,1/s.r3+1/s.r4+1/s.meter,0],[0,0,1]],[12/s.r1,12/s.r3,0]);return {va,vb,meterCurrent:(va-vb)/s.meter*1000};},'Điện kế hữu hạn có làm điện thế hai nút thay đổi so với lúc hở nhánh giữa không?',{view:'bridge',limit:'Nguồn 12 V đặt hai đầu cầu; điện kế có điện trở hữu hạn; luôn giải nút, chỉ cân bằng khi đúng tỉ số điện trở.'});
add('thevenin_norton','Nguồn tương đương Thévenin–Norton','Dòng điện','network',[p('load','Điện trở tải',10,500,100,'Ω',10),p('source2','Nguồn nhánh thứ hai',-6,6,3,'V',.5),p('r1','Điện trở nhánh nguồn 1',20,200,50,'Ω',10),p('r2','Điện trở nhánh nguồn 2',20,200,100,'Ω',10)],[q('loaded','Điện áp có tải','V'),q('open','Điện áp hở mạch','V'),q('norton','Dòng ngắn mạch có dấu','mA')],'Rth=R₁∥R₂; Eth=(E₁/R₁+E₂/R₂)Rth',s=>{const r=1/(1/s.r1+1/s.r2),open=(12/s.r1+s.source2/s.r2)*r;return {open,loaded:open*s.load/(s.load+r),norton:open/r*1000,rth:r};},'Ba cách biểu diễn nguồn có cho cùng điện áp tải khi đổi điện trở tải không?',{view:'equivalent',limit:'Nguồn 1 là 12 V; hai nhánh nguồn nối vào một nút chung qua điện trở; định lí áp dụng cho mạng tuyến tính.'});
// 15. Designing measurement circuits.
add('ammeter_shunt','Mở rộng thang ampe kế bằng shunt','Dòng điện','measurement',[p('range','Dòng toàn thang cần đo',.01,2,.5,'A',.01),p('galvanometer','Dòng toàn thang điện kế',.5,2,1,'mA',.1),p('resistance','Điện trở điện kế',50,200,100,'Ω',10)],[q('shunt','Điện trở shunt cần mắc','Ω',4),q('burden','Điện áp rơi toàn thang','V',4),q('shuntPower','Công suất shunt toàn thang','W',4)],'Rs=RgIg/(Imax−Ig)',s=>{const Ig=s.galvanometer/1000,shunt=s.resistance*Ig/(s.range-Ig);return {shunt,burden:s.resistance*Ig,shuntPower:(s.range-Ig)**2*shunt};},'Phần lớn dòng đi qua điện kế hay qua điện trở shunt?',{extra:false,view:'shunt',limit:'Điện kế tuyến tính, điện trở không đổi; Imax>Ig trong miền khảo sát; đây là thiết kế mô hình, không đo điện lưới.'});
add('voltmeter_design','Tạo vôn kế từ điện kế','Dòng điện','measurement',[p('range','Điện áp toàn thang',1,30,10,'V',.5),p('galvanometer','Dòng toàn thang điện kế',.5,2,1,'mA',.1),p('resistance','Điện trở điện kế',50,200,100,'Ω',10)],[q('series','Điện trở phụ nối tiếp','Ω'),q('input','Điện trở vào vôn kế','Ω'),q('power','Công suất toàn dụng cụ','mW')],'Rp=Umax/Ig−Rg',s=>({series:s.range/(s.galvanometer/1000)-s.resistance,input:s.range/(s.galvanometer/1000),power:s.range*s.galvanometer}),'Tăng thang điện áp trong khi giữ điện kế có làm điện trở vào tăng không?',{extra:false,view:'voltmeter',limit:'Điện kế tuyến tính; điện trở phụ dương trong toàn miền đã chọn; nguồn đo không được giả định vô hạn công suất.'});
add('emf_compensation','Đo suất điện động bằng phương pháp bù','Dòng điện','measurement',[p('unknownLength','Chiều dài cân bằng nguồn chưa biết',10,90,50,'cm',2),p('referenceLength','Chiều dài cân bằng nguồn chuẩn',20,70,40,'cm',2)],[q('emf','Suất điện động suy ra','V',4),q('gradient','Độ giảm thế trên dây','mV/cm'),q('ratio','Tỉ số hai suất điện động')],'Ex/Echuẩn=lx/lchuẩn',s=>({emf:1.018*s.unknownLength/s.referenceLength,gradient:1018/s.referenceLength,ratio:s.unknownLength/s.referenceLength}),'Vì sao ở điểm bù phép đo không cần biết điện trở trong nguồn chưa biết?',{view:'null',limit:'Dây đồng chất có gradient thế ổn định; nguồn chuẩn 1,018 V; các chiều dài là số đọc khi điện kế chỉ 0.'});
add('rc_meter_loading','Vôn kế hữu hạn khi đo tụ đang nạp','Dòng điện','measurement',[p('meter','Điện trở vôn kế',1000,100000,10000,'Ω',1000,0),p('resistance','Điện trở nạp',100,2000,1000,'Ω',100,0),p('capacity','Điện dung',10,1000,200,'µF',10)],[q('voltage','Điện áp trên tụ','V'),q('final','Điện áp ổn định','V'),q('timeConstant','Hằng số thời gian thực','s',4)],'U∞=E·Rm/(R+Rm); τ=(R∥Rm)C',s=>{const timeConstant=s.resistance*s.meter/(s.resistance+s.meter)*s.capacity*1e-6,final=12*s.meter/(s.resistance+s.meter);return {timeConstant,final,voltage:final*(1-Math.exp(-s.t/timeConstant))};},'Vôn kế làm thay đổi cả điện áp cuối và tốc độ nạp như thế nào?',{time:true,duration:(s,d)=>5*d.timeConstant,view:'rc',limit:'Nguồn 12 V, tụ ban đầu chưa tích điện; vôn kế mắc song song tụ và được mô hình bằng điện trở hữu hạn.'});
add('kelvin_four_wire','Đo điện trở bằng bốn dây Kelvin','Dòng điện','measurement',[p('sample','Điện trở mẫu',.01,5,.1,'Ω',.01,3),p('lead','Điện trở mỗi dây cấp dòng',.01,2,.2,'Ω',.01),p('current','Dòng đo',.1,2,1,'A',.1)],[q('twoWire','Điện trở đo hai dây','Ω',4),q('fourWire','Điện trở đo bốn dây','Ω',4),q('voltage','Điện áp hai đầu mẫu','mV')],'Rhai dây=Rx+2Rdây; Rbốn dây=Uđo/I',s=>({twoWire:s.sample+2*s.lead,fourWire:s.sample,voltage:1000*s.current*s.sample}),'Tại sao dây cảm biến riêng giúp loại ảnh hưởng của điện trở dây cấp dòng?',{view:'kelvin',limit:'Nguồn dòng lí tưởng, vôn kế trở vào vô hạn, dây cảm biến không mang dòng; bỏ tự nung nóng và điện áp nhiệt tiếp xúc.'});
// 16. Switching and charge transfer.
add('two_stage_rc','Hai tầng RC được cách li bằng bộ đệm','Dòng điện','transient',[p('tau1','Hằng số thời gian tầng 1',.05,2,.3,'s',.05),p('tau2','Hằng số thời gian tầng 2',.05,2,.8,'s',.05)],[q('out','Điện áp ra tầng 2','V'),q('first','Điện áp ra tầng 1','V'),q('lag','Chênh điện áp hai tầng','V')],'U₂=E[1−(τ₁e⁻ᵗᐟτ₁−τ₂e⁻ᵗᐟτ₂)/(τ₁−τ₂)]',s=>{const first=-12*Math.expm1(-s.t/s.tau1),out=12*bufferedRCStep(s.t,s.tau1,s.tau2);return {out,first,lag:first-out};},'Hai tầng liên tiếp có đáp ứng giống một tầng với hằng số thời gian cộng lại không?',{time:true,duration:s=>6*Math.max(s.tau1,s.tau2),view:'cascade',limit:'Nguồn bước 12 V; có bộ đệm lí tưởng giữa hai tầng nên không tải lẫn nhau; tụ ban đầu chưa tích điện; xử lí riêng τ₁=τ₂.'});
add('charge_sharing','Nối hai tụ đã tích điện khác nhau','Điện trường','transient',[p('c1','Điện dung tụ 1',10,500,100,'µF',10),p('c2','Điện dung tụ 2',10,500,200,'µF',10),p('u1','Điện áp ban đầu tụ 1',0,12,9,'V',.5),p('u2','Điện áp ban đầu tụ 2',0,12,3,'V',.5)],[q('final','Điện áp chung cuối','V'),q('lost','Điện trường mất năng lượng','µJ'),q('charge','Tổng điện tích bảo toàn','µC')],'Uf=(C₁U₁+C₂U₂)/(C₁+C₂)',s=>({final:(s.c1*s.u1+s.c2*s.u2)/(s.c1+s.c2),lost:.5*s.c1*s.c2/(s.c1+s.c2)*(s.u1-s.u2)**2,charge:s.c1*s.u1+s.c2*s.u2}),'Điện tích bảo toàn nhưng vì sao năng lượng điện trường giảm?',{extra:false,view:'sharing',limit:'Nối các bản cùng dấu qua dây có điện trở rất nhỏ, không nguồn; chỉ xét trước và sau khi cân bằng, năng lượng thiếu chuyển thành nhiệt và bức xạ.'});
function rlcState(s){const C=s.capacity*1e-6,w0=1/Math.sqrt(s.inductance*C),a=s.resistance/(2*s.inductance),t=s.t;let f,df,regime;if(Math.abs(a-w0)<1e-7*w0){regime=1;f=(1+a*t)*Math.exp(-a*t);df=-a*a*t*Math.exp(-a*t);}else if(a<w0){regime=0;const w=Math.sqrt(w0*w0-a*a);f=Math.exp(-a*t)*(Math.cos(w*t)+a/w*Math.sin(w*t));df=-Math.exp(-a*t)*w0*w0/w*Math.sin(w*t);}else{regime=2;const b=Math.sqrt(a*a-w0*w0),r1=-w0*w0/(a+b),r2=-a-b;f=(-r2*Math.exp(r1*t)+r1*Math.exp(r2*t))/(r1-r2);df=r1*r2*(Math.exp(r2*t)-Math.exp(r1*t))/(r1-r2);}const voltage=6*f,i=6*C*df;return {voltage,current:i*1000,energy:(.5*C*voltage*voltage+.5*s.inductance*i*i)*1e6,regime,w0,a};}
add('rlc_free','RLC tự do: ba chế độ tắt dần','Điện từ','transient',[p('resistance','Điện trở',.5,200,20,'Ω',.5),p('inductance','Độ tự cảm',.1,2,.5,'H',.1),p('capacity','Điện dung',100,1000,500,'µF',50)],[q('voltage','Điện áp tụ','V'),q('current','Dòng theo chiều nạp tụ','mA'),q('energy','Năng lượng điện từ còn lại','µJ')],'Lq̈+Rq̇+q/C=0; so sánh R/(2L) với 1/√LC',rlcState,'Tăng điện trở có làm hệ chuyển từ dao động sang trở về cân bằng không dao động không?',{time:true,view:'rlc',duration:(s,d)=>d.a<d.w0?Math.min(5/d.a,16*pi/Math.sqrt(d.w0*d.w0-d.a*d.a)):5/(d.w0*d.w0/(d.a+Math.sqrt(Math.max(0,d.a*d.a-d.w0*d.w0)))),limit:'Tụ ban đầu 6 V, dòng ban đầu 0; lời giải riêng cho dưới, tới hạn và quá tắt dần; không có nguồn cấp sau khi bắt đầu.'});
add('rc_square','Tụ RC nhận chuỗi xung vuông','Dòng điện','transient',[p('frequency','Tần số xung',.2,5,1,'Hz',.1),p('tau','Hằng số thời gian RC',.05,2,.4,'s',.05)],[q('voltage','Điện áp tụ','V'),q('input','Điện áp nguồn','V'),q('ripple','Biên độ gợn đỉnh–đỉnh','V')],'Umin=Ea/(1+a); Umax=E/(1+a), a=e⁻ᵀᐟ²τ',s=>{const half=.5/s.frequency,a=Math.exp(-half/s.tau),phase=s.t%(2*half),lo=12*a/(1+a),hi=12/(1+a);return {voltage:phase<half?12+(lo-12)*Math.exp(-phase/s.tau):hi*Math.exp(-(phase-half)/s.tau),input:phase<half?12:0,ripple:hi-lo};},'Khi RC lớn so với chu kì xung, điện áp tụ gần xung vuông hay gần một mức trung bình?',{time:true,duration:s=>3/s.frequency,view:'square',limit:'Nguồn luân phiên 0 và 12 V, duty 50%; hiển thị trạng thái tuần hoàn đã xác lập, không phải lần đóng nguồn đầu tiên.'});
add('flyback_diode','Ngắt cuộn cảm qua diode hồi tiếp','Điện từ','transient',[p('inductance','Độ tự cảm',.1,1,.5,'H',.1),p('initial','Dòng trước khi ngắt',.1,2,1,'A',.1),p('resistance','Điện trở cuộn dây',1,20,5,'Ω',1)],[q('current','Dòng còn lại','A',4),q('diodeEnergy','Năng lượng trên diode','mJ'),q('copperHeat','Nhiệt trên điện trở','mJ')],'L dI/dt + RI + Vf = 0 khi I>0',s=>{const end=s.inductance/s.resistance*Math.log(1+s.resistance*s.initial/.7),t=Math.min(s.t,end),a=s.resistance*t/s.inductance,current=Math.max(0,(s.initial+.7/s.resistance)*Math.exp(-a)-.7/s.resistance),charge=(s.initial+.7/s.resistance)*s.inductance/s.resistance*(1-Math.exp(-a))-.7*t/s.resistance,diodeEnergy=Math.max(0,.7*charge);return {current,diodeEnergy:diodeEnergy*1000,copperHeat:Math.max(0,.5*s.inductance*(s.initial**2-current**2)-diodeEnergy)*1000,end};},'Diode tạo đường duy trì dòng rồi phân tán năng lượng từ trường như thế nào?',{time:true,duration:(s,d)=>d.end,view:'flyback',limit:'Diode sụt áp cố định 0,7 V, nguồn đã ngắt, cuộn có điện trở R; bỏ điện dung kí sinh và phục hồi ngược.'});
// 17. Semiconductor signal circuits.
add('half_rectifier','Chỉnh lưu nửa chu kì','Dòng điện','electronics',[p('peak','Biên độ nguồn xoay chiều',1,20,12,'V',.5),p('frequency','Tần số nguồn',10,60,50,'Hz',2),resistance()],[q('output','Điện áp ra','V'),q('input','Điện áp vào','V'),q('current','Dòng qua tải','mA')],'ura=max(0, U₀sinωt−0,7 V)',s=>{const input=s.peak*Math.sin(2*pi*s.frequency*s.t),output=Math.max(0,input-.7);return {input,output,current:1000*output/s.resistance};},'Nửa chu kì âm của nguồn đi đâu trong điện áp tải?',{time:true,duration:s=>3/s.frequency,view:'half',limit:'Một diode mô hình ngưỡng 0,7 V, tải thuần trở, không tụ lọc, không đánh thủng ngược.'});
add('bridge_rectifier','Cầu chỉnh lưu toàn chu kì','Dòng điện','electronics',[p('peak','Biên độ nguồn xoay chiều',2,20,12,'V',.5),p('frequency','Tần số nguồn',10,60,50,'Hz',2),resistance()],[q('output','Điện áp tải','V'),q('input','Điện áp nguồn','V'),q('current','Dòng tải cùng chiều','mA')],'ura=max(0,|U₀sinωt|−1,4 V)',s=>{const input=s.peak*Math.sin(2*pi*s.frequency*s.t),output=Math.max(0,Math.abs(input)-1.4);return {input,output,current:1000*output/s.resistance};},'Vì sao dòng tải giữ cùng chiều trong cả hai nửa chu kì?',{time:true,duration:s=>3/s.frequency,view:'bridge',limit:'Mỗi lúc có hai diode dẫn, mỗi diode sụt 0,7 V; tải thuần trở, bỏ quá độ chuyển mạch.'});
add('rectifier_filter','Tụ lọc và độ gợn sau chỉnh lưu','Dòng điện','electronics',[p('capacity','Điện dung lọc',100,2000,500,'µF',50),p('resistance','Điện trở tải',500,5000,1000,'Ω',100),p('frequency','Tần số nguồn',40,60,50,'Hz',2)],[q('mean','Điện áp trung bình gần đúng','V'),q('ripple','Gợn đỉnh–đỉnh gần đúng','V'),q('percent','Gợn / điện áp trung bình','%')],'ΔU≈I/(2fC); Ū≈Uđỉnh−1,4−ΔU/2',s=>{const C=s.capacity*1e-6,mean=10.6/(1+1/(4*s.frequency*s.resistance*C)),ripple=mean/(2*s.frequency*s.resistance*C);return {mean,ripple,percent:100*ripple/mean};},'Tăng điện dung giúp làm phẳng điện áp bằng cách nào?',{view:'filter',limit:'Nguồn đỉnh 12 V qua cầu chỉnh lưu; gần đúng gợn nhỏ, bỏ thời gian dẫn và trở nguồn; nếu tỉ lệ gợn lớn, không dùng để thiết kế mạch thực.'});
add('zener_regulator','Ổn áp Zener và giới hạn dòng','Dòng điện','electronics',[p('input','Điện áp nguồn',5,20,12,'V',.5),p('series','Điện trở hạn dòng',100,1000,330,'Ω',10),p('load','Điện trở tải',500,10000,2000,'Ω',100)],[q('output','Điện áp ra hợp lệ','V'),q('zenerCurrent','Dòng Zener theo mô hình','mA'),q('power','Công suất Zener theo mô hình','mW')],'Iz=(Uin−Uz)/Rs−Uz/RL; 0≤UzIz≤Pmax',s=>{const trial=(s.input-5.1)/s.series-5.1/s.load,Iz=Math.max(0,trial),power=5.1*Iz;return {output:power>.5?null:trial>0?5.1:s.input*s.load/(s.series+s.load),zenerCurrent:Iz*1000,power:power*1000,regulated:trial>=0&&power<=.5?1:0};},'Tăng tải có thể làm diode mất khả năng ổn áp vì sao?',{view:'zener',limit:'Uz=5,1 V, giới hạn công suất mô hình 0,5 W; dưới ngưỡng thì diode không dẫn; vượt công suất chỉ cảnh báo, không giả lập hỏng linh kiện.'});
add('diode_clipper','Xén tín hiệu bằng hai diode đối song','Dòng điện','electronics',[p('phase','Pha tín hiệu',0,360,60,'°',5),p('peak','Biên độ điện áp vào',.1,5,2,'V',.1),resistance()],[q('output','Điện áp sau xén','V'),q('input','Điện áp vào','V'),q('current','Dòng qua điện trở có dấu','mA')],'ura≈giới hạn(uin,−0,7 V,+0,7 V)',s=>{const input=s.peak*Math.sin(rad(s.phase)),output=clamp(input,-.7,.7);return {input,output,current:1000*(input-output)/s.resistance};},'Khi tín hiệu vào nhỏ hơn ngưỡng, mạch có làm biến dạng điện áp ra không?',{view:'clipper',limit:'Hai diode đối song đặt sau điện trở hạn dòng; mô hình ngưỡng đối xứng, không xét dòng rò và điện dung tiếp giáp.'});
// 18. AC transfer functions and reactive power.
add('rc_lowpass','Bộ lọc RC thông thấp','Dòng điện','ac_network',[p('frequency','Tần số khảo sát',10,10000,1000,'Hz',10),p('resistance','Điện trở',100,10000,1000,'Ω',100),p('capacity','Điện dung',.01,1,.1,'µF',.01)],[q('gain','Tỉ số biên độ ra / vào'),q('phase','Pha điện áp ra trừ vào','°'),q('cutoff','Tần số cắt','Hz')],'H=1/(1+jωRC)',s=>{const x=2*pi*s.frequency*s.resistance*s.capacity*1e-6;return {gain:1/Math.hypot(1,x),phase:-deg(Math.atan(x)),cutoff:1/(2*pi*s.resistance*s.capacity*1e-6)};},'Ở tần số cắt, biên độ điện áp bằng một nửa hay bằng 1/√2 điện áp vào?',{view:'lowpass',limit:'Điện áp ra lấy trên tụ, tải vô hạn, nguồn lí tưởng; trạng thái hình sin ổn định.'});
add('rc_highpass','Bộ lọc RC thông cao','Dòng điện','ac_network',[p('frequency','Tần số khảo sát',10,10000,1000,'Hz',10),p('resistance','Điện trở',100,10000,1000,'Ω',100),p('capacity','Điện dung',.01,1,.1,'µF',.01)],[q('gain','Tỉ số biên độ ra / vào'),q('phase','Pha điện áp ra trừ vào','°'),q('cutoff','Tần số cắt','Hz')],'H=jωRC/(1+jωRC)',s=>{const x=2*pi*s.frequency*s.resistance*s.capacity*1e-6;return {gain:x/Math.hypot(1,x),phase:deg(Math.atan2(1,x)),cutoff:1/(2*pi*s.resistance*s.capacity*1e-6)};},'Đổi chỗ lấy điện áp ra từ tụ sang điện trở làm thay đổi miền tần số được truyền thế nào?',{view:'highpass',limit:'Điện áp ra lấy trên điện trở trong mạch RC nối tiếp; tải vô hạn, nguồn lí tưởng, đáp ứng ổn định.'});
add('rlc_bandwidth','Bộ lọc RLC thông dải và băng thông','Điện từ','ac_network',[p('frequency','Tần số khảo sát',10,500,100,'Hz',5),p('resistance','Điện trở',5,100,20,'Ω',1),p('inductance','Độ tự cảm',.05,.5,.1,'H',.01),p('capacity','Điện dung',10,200,50,'µF',5)],[q('gain','Biên độ áp trên R / nguồn'),q('bandwidth','Băng thông nửa công suất','Hz'),q('quality','Hệ số phẩm chất Q')],'Δf=R/(2πL); Q=ω₀L/R',s=>{const L=s.inductance,C=s.capacity*1e-6,w=2*pi*s.frequency,x=w*L-1/(w*C);return {gain:s.resistance/Math.hypot(s.resistance,x),bandwidth:s.resistance/(2*pi*L),quality:Math.sqrt(L/C)/s.resistance,resonance:1/(2*pi*Math.sqrt(L*C))};},'Giảm điện trở giúp chọn dải hẹp hơn nhưng có làm hệ số Q tăng không?',{view:'bandpass',limit:'Mạch RLC nối tiếp, áp ra trên R, phần tử lí tưởng; băng thông lấy tại công suất bằng nửa cực đại.'});
add('ac_capacitance_bridge','Cầu xoay chiều đo điện dung','Dòng điện','ac_network',[p('r1','Điện trở tỉ lệ R1',100,2000,500,'Ω',100),p('r2','Điện trở tỉ lệ R2',100,2000,1000,'Ω',100),p('reference','Điện dung chuẩn',.01,1,.1,'µF',.01),p('frequency','Tần số nguồn',10,1000,100,'Hz',10)],[q('unknown','Điện dung suy ra','µF',4),q('reactance','Dung kháng tụ chưa biết','Ω'),q('ratio','Tỉ số điện dung')],'Cx=Cchuẩn·R1/R2 tại cân bằng',s=>({unknown:s.reference*s.r1/s.r2,reactance:1/(2*pi*s.frequency*s.reference*s.r1/s.r2*1e-6),ratio:s.r1/s.r2}),'Vì sao giá trị điện dung suy ra ở cân bằng không phụ thuộc tần số nguồn lí tưởng?',{view:'capacitive_bridge',limit:'Cầu De Sauty, tụ không tổn hao; nhánh tỉ lệ R1/R2 bằng Cx/Cchuẩn theo cách đánh dấu trên sơ đồ; số nhập là giá trị tại điểm cân bằng.'});
add('power_factor','Bù hệ số công suất cho tải cảm','Điện từ','ac_network',[p('capacity','Điện dung bù song song',0,150,50,'µF',5),p('reactiveLoad','Công suất phản kháng tải cảm',100,2000,1000,'var',50,0),p('active','Công suất tác dụng tải',100,2000,800,'W',50,0)],[q('factor','Hệ số công suất'),q('lineCurrent','Dòng nguồn RMS','A'),q('reactive','Công suất phản kháng thuần','var')],'Qc=ωCU²; S²=P²+(QL−Qc)²',s=>{const reactive=s.reactiveLoad-2*pi*50*s.capacity*1e-6*230**2,S=Math.hypot(s.active,reactive);return {reactive,factor:s.active/S,lineCurrent:S/230,idealCapacity:s.reactiveLoad/(2*pi*50*230**2)*1e6};},'Bù quá mức có thể làm dòng nguồn tăng trở lại không?',{view:'compensation',limit:'Nguồn 230 V RMS, 50 Hz; tải giữ P và QL cố định; tụ lí tưởng, mô hình học tập không hướng dẫn đấu điện lưới.'});
// 19. Finite magnetic geometries.
add('loop_axis','Từ trường trên trục vòng dây tròn','Điện từ','magnetic_geometry',[p('distance','Tọa độ trên trục',-.5,.5,.1,'m',.02),p('radius','Bán kính vòng',.05,.4,.15,'m',.01),p('current','Dòng điện',.1,5,2,'A',.1)],[q('field','Từ trường dọc trục','µT'),q('center','Từ trường tại tâm','µT'),q('ratio','B tại đầu dò / B tâm')],'Bz=µ₀NIa²/[2(a²+z²)³ᐟ²]',s=>{const center=mu*100*s.current/(2*s.radius)*1e6,ratio=(s.radius**2/(s.radius**2+s.distance**2))**1.5;return {center,ratio,field:center*ratio};},'Đi xa tâm trên trục làm trường giảm theo cùng quy luật dây thẳng dài không?',{grade:12,view:'loop',limit:'100 vòng mảnh đồng phẳng, cùng bán kính; trường trong chân không, chỉ khảo sát trên trục.'});
add('helmholtz_coils','Cuộn Helmholtz và vùng trường gần đều','Điện từ','magnetic_geometry',[p('distance','Tọa độ đầu dò trên trục',-.3,.3,.05,'m',.01),p('radius','Bán kính mỗi cuộn',.1,.4,.2,'m',.01),p('current','Dòng qua hai cuộn',.1,5,2,'A',.1)],[q('field','Từ trường tại đầu dò','µT'),q('center','Trường tại trung điểm','µT'),q('deviation','Độ lệch so với trung điểm','%')],'B(z)=Bvòng(z−a/2)+Bvòng(z+a/2)',s=>{const f=z=>mu*100*s.current*s.radius**2/(2*(s.radius**2+z*z)**1.5)*1e6,field=f(s.distance-s.radius/2)+f(s.distance+s.radius/2),center=mu*100*s.current/s.radius*(4/5)**1.5*1e6;return {field,center,deviation:100*(field/center-1)};},'Vùng trường gần đều trải rộng toàn không gian hay chỉ quanh trung điểm?',{grade:12,view:'helmholtz',limit:'Hai cuộn 100 vòng, cùng chiều dòng, khoảng cách bằng bán kính; cộng trường hai vòng tròn, không giả định trường đều ở xa.'});
add('finite_solenoid','Ống dây hữu hạn: trường gần hai đầu','Điện từ','magnetic_geometry',[p('distance','Tọa độ đầu dò trên trục',-.8,.8,.1,'m',.02),p('length','Chiều dài ống dây',.1,1,.4,'m',.05),p('radius','Bán kính ống dây',.02,.15,.05,'m',.01)],[q('field','Trường trên trục','µT'),q('longApprox','Giá trị gần đúng ống rất dài','µT'),q('ratio','Tỉ số hai mô hình')],'B=µ₀nI[(z+L/2)/r₊−(z−L/2)/r₋]/2',s=>{const a=s.distance+s.length/2,b=s.distance-s.length/2,longApprox=mu*300/s.length*2*1e6,field=longApprox/2*(a/Math.hypot(a,s.radius)-b/Math.hypot(b,s.radius));return {field,longApprox,ratio:field/longApprox};},'Gần đầu ống, công thức ống dây rất dài dự đoán sai khác ra sao?',{grade:12,view:'solenoid',limit:'Ống 300 vòng phân bố đều, dòng 2 A; lớp dây mỏng, khảo sát đúng trên trục, không lõi từ.'});
add('toroid','Từ trường và tự cảm của cuộn xuyến','Điện từ','magnetic_geometry',[p('distance','Bán kính vị trí khảo sát',.05,.4,.2,'m',.01),p('turns','Số vòng',100,1000,300,'',50,0),p('current','Dòng qua cuộn',.1,5,2,'A',.1)],[q('field','Từ trường tại vị trí chọn','µT'),q('inductance','Độ tự cảm','mH'),q('inside','Nằm trong tiết diện xuyến: 1','',0)],'B=µ₀NI/(2πr) trong lõi không khí',s=>({field:s.distance>=.1&&s.distance<=.3?mu*Math.round(s.turns)*s.current/(2*pi*s.distance)*1e6:0,inductance:mu*Math.round(s.turns)**2*.05/(2*pi)*Math.log(3)*1000,inside:s.distance>=.1&&s.distance<=.3?1:0}),'Bên trong xuyến có phải từ trường bằng nhau ở mọi bán kính không?',{grade:12,view:'toroid',limit:'Tiết diện chữ nhật cao 0,05 m, bán kính trong 0,1 m và ngoài 0,3 m; quấn đều dày, bỏ rò trường, không lõi sắt.'});
add('compass_coil','La bàn trong trường Trái Đất và cuộn dây','Điện từ','magnetic_geometry',[p('current','Dòng cuộn có dấu',-1,1,.2,'A',.05),p('earth','Thành phần từ trường ngang Trái Đất',10,60,30,'µT',2)],[q('angle','Góc lệch kim khỏi hướng bắc','°'),q('resultant','Từ trường tổng hợp','µT'),q('coilField','Trường cuộn dây có dấu','µT')],'tanθ=Bcuộn/Bngang Trái Đất',s=>{const coilField=mu*20*s.current/(2*.1)*1e6;return {coilField,angle:deg(Math.atan2(coilField,s.earth)),resultant:Math.hypot(coilField,s.earth)};},'Đảo chiều dòng điện làm kim quay sang phía nào?',{grade:12,view:'compass',limit:'Cuộn 20 vòng bán kính 0,1 m; trường cuộn vuông góc thành phần trường Trái Đất nằm ngang, la bàn ở tâm, bỏ ma sát kim.'});
// 20. Charged-particle instruments.
add('velocity_selector','Bộ lọc vận tốc điện–từ','Điện từ','particle_device',[p('speed','Tốc độ proton tới',.5,10,2,'10⁶ m/s',.5),p('electric','Cường độ điện trường',1000,100000,20000,'V/m',1000,0),p('magnetic','Cảm ứng từ',.01,.2,.05,'T',.01)],[q('selected','Tốc độ qua thẳng','km/s'),q('force','Lực ngang có dấu','fN'),q('balance','Cân bằng lực: 1','',0)],'F=q(E−vB); vchọn=E/B',s=>({selected:s.electric/s.magnetic/1000,force:qe*(s.electric-s.speed*1e6*s.magnetic)*1e15,balance:Math.abs(s.electric-s.speed*1e6*s.magnetic)<1e-6?1:0}),'Hạt đi thẳng có phải vì cả hai lực đều bằng 0 không?',{grade:12,view:'selector',limit:'Proton đi vào với vận tốc vuông góc hai trường đều chéo nhau; biểu diễn hợp lực ban đầu, không tích phân quỹ đạo sau lệch.'});
add('mass_spectrometer','Khối phổ từ tách hai đồng vị','Điện từ','particle_device',[p('massNumber','Khối lượng ion',20,40,24,'u',1,0),p('voltage','Điện áp tăng tốc',100,5000,1000,'V',100,0),p('magnetic','Cảm ứng từ',.05,.5,.2,'T',.01)],[q('radius','Bán kính quỹ đạo','cm'),q('separation','Khoảng cách hai vết A và A+1','cm'),q('speed','Tốc độ ion','km/s')],'r=√(2mU/q)/B; khoảng cách sau nửa vòng=2r',s=>{const m=Math.round(s.massNumber)*1.6605390666e-27,r=Math.sqrt(2*m*s.voltage/qe)/s.magnetic,r2=Math.sqrt(2*(Math.round(s.massNumber)+1)*1.6605390666e-27*s.voltage/qe)/s.magnetic;return {radius:r*100,separation:2*(r2-r)*100,speed:Math.sqrt(2*qe*s.voltage/m)/1000};},'Cùng điện tích và điện áp tăng tốc, đồng vị nặng hơn chạm xa hay gần hơn?',{grade:12,view:'spectrometer',limit:'Ion điện tích +e, khối lượng A u và (A+1)u, bắt đầu gần đứng yên; qua nửa vòng trong trường đều vuông góc; không có độ rộng chùm.'});
add('cyclotron','Cyclotron phi tương đối tính','Điện từ','particle_device',[p('magnetic','Cảm ứng từ',.1,1,.5,'T',.05),p('radius','Bán kính quỹ đạo cuối',2,20,10,'cm',1),p('gapVoltage','Điện áp gia tốc mỗi khe',500,5000,1000,'V',100,0)],[q('frequency','Tần số gia tốc cộng hưởng','MHz'),q('energy','Động năng tại bán kính cuối','keV'),q('turns','Số vòng theo năng lượng liên tục')],'f=qB/(2πm); K=q²B²r²/(2m)',s=>{const m=1.672621924e-27,E=qe**2*s.magnetic**2*(s.radius/100)**2/(2*m);const classicalSpeed=qe*Math.abs(s.magnetic)*(s.radius/100)/m,domainValid=classicalSpeed<=.1*c;return {frequency:domainValid?qe*s.magnetic/(2*pi*m)/1e6:null,energy:domainValid?E/qe/1000:null,turns:domainValid?E/(2*qe*s.gapVoltage):null,classicalSpeed,domainValid,domainMessage:domainValid?'':'Ngoài miền phi tương đối tính: tốc độ cổ điển vượt 0,1c. Hãy giảm cảm ứng từ hoặc bán kính trước khi đo.'};},'Vì sao chu kì quỹ đạo chưa phụ thuộc tốc độ trong xấp xỉ phi tương đối tính?',{grade:12,view:'cyclotron',limit:'Proton, trường đều, mỗi vòng qua hai khe; giới hạn xấp xỉ công bố v ≤ 0,1c (sai lệch động học tương đối tính cỡ 1% hoặc nhỏ hơn). Ngoài miền này không báo số đo cổ điển như kết quả hợp lệ. Số vòng ước lượng liên tục, chưa mô phỏng đồng bộ pha.'});
add('magnetic_helix','Quỹ đạo xoắn ốc trong từ trường','Điện từ','particle_device',[p('angle','Góc vận tốc với từ trường',0,90,45,'°',2),p('speed','Tốc độ proton',.1,2,1,'10⁶ m/s',.1),p('magnetic','Cảm ứng từ',.01,.2,.05,'T',.01)],[q('radius','Bán kính đường xoắn','cm'),q('pitch','Bước xoắn','cm'),q('period','Chu kì quay','µs')],'r=mv sinα/(qB); bước=v cosα·2πm/(qB)',s=>{const T=2*pi*1.672621924e-27/(qe*s.magnetic),v=s.speed*1e6;return {radius:1.672621924e-27*v*Math.sin(rad(s.angle))/(qe*s.magnetic)*100,pitch:v*Math.cos(rad(s.angle))*T*100,period:T*1e6};},'Thành phần vận tốc nào tạo vòng quay và thành phần nào tạo bước xoắn?',{grade:12,view:'helix',limit:'Proton phi tương đối tính, từ trường đều, không điện trường và không va chạm; hình được thay đổi tỉ lệ.'});
add('hall_voltage','Hiệu ứng Hall và dấu hạt tải','Điện từ','particle_device',[p('magnetic','Cảm ứng từ có dấu',-.5,.5,.2,'T',.05),p('current','Dòng điện quy ước',.1,5,1,'A',.1),p('density','Mật độ hạt tải',1,1000,100,'10²² m⁻³',10,0),p('type','Hạt tải: 0 âm; 1 dương',0,1,0,'',1,0)],[q('voltage','Điện áp Hall có dấu','µV'),q('coefficient','Hệ số Hall','10⁻⁶ m³/C',4),q('chargeSign','Dấu hạt tải','',0)],'VH=IB/(nqt)',s=>{const sign=Math.round(s.type)===0?-1:1,coef=1/(s.density*1e22*sign*qe);return {voltage:s.current*s.magnetic*coef/.001*1e6,coefficient:coef*1e6,chargeSign:sign};},'Đổi chiều từ trường và đổi dấu hạt tải có tác dụng giống nhau lên dấu Hall không?',{grade:12,view:'hall',limit:'Bản dày 1 mm, một loại hạt tải; dòng dọc +x, B theo +z, VH theo quy ước cân bằng điện–từ ở chiều +y; bỏ hiệu ứng nhiều dải.'});
// 21. Induction and back-reaction.
add('sliding_rod','Thanh trượt trên ray và lực hãm','Điện từ','induction_device',[p('speed','Vận tốc thanh có dấu',-5,5,2,'m/s',.2),p('magnetic','Cảm ứng từ',.1,1,.5,'T',.05),p('length','Chiều dài thanh',.2,1,.5,'m',.05),p('resistance','Điện trở toàn mạch',1,20,5,'Ω',1)],[q('emf','Suất điện động cảm ứng','V'),q('current','Dòng cảm ứng có dấu','A'),q('force','Lực từ theo trục chuyển động','N')],'e=BLv; I=e/R; F=−BLI',s=>{const emf=s.magnetic*s.length*s.speed,current=emf/s.resistance,force=-s.magnetic*s.length*current;return {emf,current,force,power:-force*s.speed,heat:current**2*s.resistance};},'Công của lực kéo giữ vận tốc chuyển thành nhiệt trên điện trở như thế nào?',{grade:12,extra:false,view:'rod',limit:'Ray nhẵn, B vuông góc mặt ray, thanh giữ vận tốc không đổi bằng ngoại lực; bỏ tự cảm và điện trở tiếp xúc.'});
add('magnetic_braking','Hãm từ và cơ năng chuyển thành nhiệt','Điện từ','induction_device',[p('magnetic','Cảm ứng từ',.5,2,1,'T',.1),p('mass','Khối lượng thanh',.1,1,.3,'kg',.05),p('resistance','Điện trở mạch',1,10,3,'Ω',.5)],[q('speed','Tốc độ còn lại','m/s'),q('heat','Nhiệt đã tỏa','J'),q('distance','Quãng đường đã đi','m')],'v=v₀e⁻ᵗᐟτ; τ=mR/(B²L²)',s=>{const tau=s.mass*s.resistance/(s.magnetic**2*.5**2),speed=3*Math.exp(-s.t/tau);return {speed,heat:.5*s.mass*(9-speed*speed),distance:3*tau*(1-Math.exp(-s.t/tau)),tau};},'Kiểm tra tổng động năng còn lại và nhiệt tỏa ra có giữ nguyên không?',{grade:12,extra:false,time:true,duration:(s,d)=>5*d.tau,view:'braking',limit:'Thanh dài 0,5 m, tốc độ đầu 3 m/s, không lực kéo hay ma sát cơ; bỏ tự cảm và điện trở thay đổi do nóng.'});
add('coil_entering_field','Khung dây đi qua vùng từ trường hữu hạn','Điện từ','induction_device',[p('magnetic','Cảm ứng từ',.1,1,.5,'T',.05),p('turns','Số vòng khung',1,50,10,'',1,0),p('resistance','Điện trở mạch',1,50,10,'Ω',1)],[q('emf','Suất điện động cảm ứng','V'),q('flux','Từ thông móc vòng','Wb'),q('current','Dòng có dấu','A')],'e=−NB dSphủ/dt',s=>{const x=s.t-1,w=.8,L=2,overlap=clamp(x+w,0,L)-clamp(x,0,L),slope=(x+w>0&&x+w<L?1:0)-(x>0&&x<L?1:0),emf=-Math.round(s.turns)*s.magnetic*slope;return {emf,flux:Math.round(s.turns)*s.magnetic*overlap,current:emf/s.resistance,x};},'Vì sao suất điện động bằng 0 khi khung nằm hoàn toàn trong vùng trường đều?',{grade:12,extra:false,time:true,window:4,view:'entering',limit:'Khung rộng 0,8 m cao 1 m, vùng B rộng 2 m, tốc độ 1 m/s; bỏ tự cảm, bỏ quá độ tại các mép lí tưởng.'});
add('mutual_induction','Hai cuộn dây và hỗ cảm','Điện từ','induction_device',[p('coupling','Hệ số ghép từ',0,1,.6,'',.05),p('frequency','Tần số dòng sơ cấp',.2,5,1,'Hz',.1),p('inductance','Độ tự cảm mỗi cuộn',.05,.5,.1,'H',.01)],[q('emf','Suất điện động thứ cấp','V'),q('current','Dòng sơ cấp','A'),q('mutual','Hỗ cảm','mH')],'M=k√(L₁L₂); e₂=−M dI₁/dt',s=>({emf:-s.coupling*s.inductance*2*pi*s.frequency*Math.cos(2*pi*s.frequency*s.t),current:Math.sin(2*pi*s.frequency*s.t),mutual:s.coupling*s.inductance*1000}),'Dòng sơ cấp đạt cực đại thì suất điện động thứ cấp có đạt cực đại không?',{grade:12,time:true,duration:s=>3/s.frequency,view:'mutual',limit:'Hai cuộn bằng L, hình học cố định, I₁ do nguồn dòng lí tưởng duy trì biên độ 1 A; thứ cấp hở, không phản hồi lên sơ cấp.'});
add('faraday_disk','Máy phát đĩa Faraday','Điện từ','induction_device',[p('omega','Tốc độ góc',10,200,80,'rad/s',5),p('radius','Bán kính đĩa',.05,.3,.15,'m',.01),p('magnetic','Cảm ứng từ',.1,1,.5,'T',.05)],[q('emf','Điện áp vành trừ tâm','V',4),q('current','Dòng tải','mA'),q('torque','Độ lớn mômen cản','mN·m')],'e=BωR²/2; M=IBR²/2',s=>{const emf=.5*s.magnetic*s.omega*s.radius**2,current=emf/10;return {emf,current:current*1000,torque:.5*current*s.magnetic*s.radius**2*1000,theta:s.omega*s.t};},'Dòng tải sinh mômen cản hay mômen cùng chiều quay?',{grade:12,time:true,duration:s=>6*pi/s.omega,view:'disk',limit:'Đĩa dẫn quay đều trong B dọc trục, tải 10 Ω, tiếp điểm lí tưởng; tốc độ được ngoại lực giữ cố định.'});
// 22. Electromagnetic-wave energy and conductors.
add('em_plane_wave','Điện trường và từ trường trong sóng phẳng','Điện từ','em_wave',[p('position','Vị trí dọc hướng truyền',0,3,.5,'m',.05),p('frequency','Tần số sóng',100,1000,300,'MHz',10,0),p('amplitude','Biên độ điện trường',1,100,30,'V/m',1)],[q('electric','Điện trường tức thời theo y','V/m'),q('magnetic','Từ trường tức thời theo z','nT'),q('wavelength','Bước sóng','m')],'E=cB; E và B cùng pha, vuông góc hướng truyền',s=>{const wavelength=c/(s.frequency*1e6),electric=s.amplitude*Math.cos(2*pi*s.position/wavelength);return {electric,magnetic:electric/c*1e9,wavelength};},'Khi điện trường đổi dấu theo y, từ trường đổi thế nào để hướng truyền giữ nguyên?',{grade:12,view:'plane',limit:'Sóng phẳng đơn sắc trong chân không, hình là ảnh chụp không gian tại t=0; E và B là trường, không phải sợi dây dao động.'});
add('poynting_energy','Vectơ Poynting và năng lượng sóng','Điện từ','em_wave',[p('phase','Pha tại điểm quan sát',0,360,45,'°',5),p('amplitude','Biên độ điện trường',1,1000,100,'V/m',10)],[q('instant','Mật độ dòng năng lượng tức thời','W/m²'),q('average','Cường độ trung bình','W/m²'),q('density','Mật độ năng lượng trung bình','µJ/m³')],'S=E×B/µ₀; Ī=ε₀cE₀²/2',s=>{const average=.5*eps*c*s.amplitude**2;return {average,instant:2*average*Math.cos(rad(s.phase))**2,density:average/c*1e6};},'Trường đổi dấu mỗi nửa chu kì có làm dòng năng lượng đổi hướng không?',{grade:12,view:'energy',limit:'Sóng phẳng chạy một chiều trong chân không; đại lượng trung bình lấy theo một chu kì, không phải hiệu dụng của chuyển vị cơ.'});
add('radiation_pressure','Áp suất ánh sáng trên mặt hấp thụ và phản xạ','Vật lí hiện đại','em_wave',[p('reflectivity','Tỉ phần năng lượng phản xạ',0,1,.5,'',.05),p('intensity','Cường độ ánh sáng',10,2000,1000,'W/m²',50),p('area','Diện tích chiếu',.01,1,.1,'m²',.01)],[q('pressure','Áp suất bức xạ','µPa'),q('force','Lực lên mặt','µN'),q('absorbed','Công suất hấp thụ','W')],'p=(1+r)I/c; F=pS',s=>({pressure:(1+s.reflectivity)*s.intensity/c*1e6,force:(1+s.reflectivity)*s.intensity/c*s.area*1e6,absorbed:(1-s.reflectivity)*s.intensity*s.area}),'Mặt phản xạ lí tưởng nhận lực lớn hơn mặt hấp thụ lí tưởng bao nhiêu lần?',{grade:12,view:'pressure',limit:'Tới vuông góc, mặt phẳng không truyền sáng; phần không phản xạ được hấp thụ hoàn toàn; bỏ tái bức xạ nhiệt.'});
add('transmission_reflection','Phản xạ điện áp trên đường truyền có tải','Điện từ','em_wave',[p('load','Trở tải',10,200,100,'Ω',5),p('impedance','Trở kháng đặc trưng',25,100,50,'Ω',5),p('incident','Biên độ điện áp tới',1,10,5,'V',.5)],[q('reflection','Hệ số phản xạ điện áp'),q('loadVoltage','Điện áp tổng tại tải','V'),q('powerFraction','Tỉ phần công suất được tải nhận')],'Γ=(RL−Z₀)/(RL+Z₀); Utải=Ui(1+Γ)',s=>{const reflection=(s.load-s.impedance)/(s.load+s.impedance);return {reflection,loadVoltage:s.incident*(1+reflection),powerFraction:1-reflection**2};},'Tải bằng trở kháng đặc trưng loại bỏ phản xạ vì sao?',{grade:12,view:'line',limit:'Đường truyền không hao phí, tải thuần trở; biểu diễn sóng tới và phản xạ, không giải quá trình nhiều lần phản xạ giữa nguồn và tải.'});
add('skin_depth','Độ sâu thấm điện từ trong vật dẫn','Điện từ','em_wave',[p('frequency','Tần số',100,1000000,10000,'Hz',100,0),p('radius','Bán kính dây',.1,5,1,'mm',.1),p('permeability','Độ từ thẩm tương đối giả định',1,100,1,'',1,0)],[q('depth','Độ sâu thấm δ','µm'),q('resistanceRatio','RAC/RDC trong gần đúng lớp mỏng'),q('thin','δ nhỏ hơn r/3: 1','',0)],'δ=√(2/(µσω)); RAC/RDC≈r/(2δ) nếu δ≪r',s=>{const depth=Math.sqrt(2/(mu*s.permeability*58e6*2*pi*s.frequency)),r=s.radius/1000;return {depth:depth*1e6,resistanceRatio:depth<r/3?r/(2*depth):null,thin:depth<r/3?1:0};},'Tại sao không được dùng công thức lớp mỏng khi δ lớn hơn bán kính dây?',{grade:12,view:'skin',limit:'Vật dẫn đồng σ=58 MS/m, µr giả định không phụ thuộc tần số; lớp màu minh họa suy giảm e-fold, không phải ranh giới dòng điện sắc nét.'});
// 23. Imaging systems with physically distinct objectives.
add('separated_lenses','Hai thấu kính cách nhau và ảnh trung gian','Quang học','imaging',[p('separation','Khoảng cách hai thấu kính',5,60,25,'cm',1),p('object','Khoảng cách vật tới kính 1',15,80,30,'cm',1)],[q('image','Khoảng cách ảnh sau kính 2 có dấu','cm'),q('magnification','Độ phóng đại toàn hệ'),q('intermediate','Khoảng cách ảnh trung gian','cm')],'Truyền tia bằng P(d)L₁P(u), rồi L₂; ảnh thỏa B+vD=0',s=>{const f=10,F=15,u=s.object,d=s.separation,A=1-d/f,B=u+d*(1-u/f),C=-1/f-A/F,D=1-u/f-B/F,v=Math.abs(D)<1e-10?null:-B/D;return {image:v,magnification:v===null?null:A+v*C,intermediate:f*u/(u-f),a:A,b:B,c:C,d:D};},'Ảnh trung gian có thể trở thành vật ảo đối với thấu kính thứ hai không?',{view:'two_lenses',limit:'Thấu kính mỏng cận trục, f₁=10 cm, f₂=15 cm; khoảng cách có dấu theo ma trận truyền tia; D=0 ứng với ảnh ở vô cực.'});
add('camera_defocus','Máy ảnh: khẩu độ và vòng nhòe','Quang học','imaging',[p('fNumber','Số khẩu độ f/N',1.4,16,4,'',.2),p('focus','Khoảng cách lấy nét',.5,5,2,'m',.1),p('object','Khoảng cách vật đang xét',.5,5,3,'m',.1)],[q('blur','Đường kính vòng nhòe','mm',4),q('sensor','Khoảng cách cảm biến tới kính','mm'),q('aperture','Đường kính khẩu độ','mm')],'cnhòe=D|vfocus−vvật|/vvật',s=>{const f=50,u=s.object*1000,uf=s.focus*1000,v=f*u/(u-f),sensor=f*uf/(uf-f),aperture=f/s.fNumber;return {blur:aperture*Math.abs(sensor-v)/v,sensor,aperture};},'Khép khẩu làm vòng nhòe hình học nhỏ đi, nhưng mô hình này chưa xét hiệu ứng nào?',{view:'camera',limit:'Thấu kính mỏng tiêu cự 50 mm, cảm biến cố định theo điểm lấy nét; chỉ nhòe do lệch nét, chưa cộng nhiễu xạ và quang sai.'});
add('eye_correction','Mắt mô hình và kính sửa cận thị','Quang học','imaging',[p('farPoint','Khoảng cực viễn của mắt cận',.2,5,1,'m',.1),p('object','Khoảng cách vật',.2,5,.5,'m',.1)],[q('glasses','Độ tụ kính để nhìn xa vô cực','D'),q('accommodation','Độ tăng tụ mắt cần thiết','D'),q('eyePower','Độ tụ mắt chưa điều tiết','D')],'Pkính=−1/OCv; ΔPmắt=1/OCvật−1/OCv',s=>({glasses:-1/s.farPoint,accommodation:1/s.object-1/s.farPoint,eyePower:1/.017+1/s.farPoint}),'Vật ở xa hơn cực viễn đòi độ tụ thay đổi theo chiều nào?',{view:'eye',limit:'Mắt cận mô hình có võng mạc cách thấu kính tương đương 17 mm; kính sát mắt; chỉ giải thích quang học, không phải thông số kê kính.'});
add('spherical_aberration','Cầu sai qua một mặt khúc xạ cầu','Quang học','imaging',[p('heightRatio','Độ cao tia / bán kính cong',.05,.8,.4,'',.05),p('radius','Bán kính mặt cầu',1,10,5,'cm',.5),p('index','Chiết suất môi trường sau',1.2,2,1.5,'',.05)],[q('focus','Giao trục của tia đang xét','cm'),q('paraxial','Tiêu điểm cận trục','cm'),q('aberration','Sai lệch tiêu điểm','cm')],'θra=asin(y/(nR))−asin(y/R); xf=xmặt−y/tanθra',s=>{const y=s.heightRatio*s.radius,x=s.radius*(1-Math.sqrt(1-s.heightRatio**2)),a=Math.asin(s.heightRatio/s.index)-Math.asin(s.heightRatio),focus=x-y/Math.tan(a),paraxial=s.index*s.radius/(s.index-1);return {focus,paraxial,aberration:focus-paraxial,surfaceX:x,rayHeight:y,rayAngle:a};},'Tia xa trục có gặp trục tại cùng điểm với tia cận trục không?',{view:'spherical_surface',limit:'Tia song song đi từ không khí vào môi trường qua một mặt cầu lồi; áp dụng Snell tại mặt thật, không dùng thấu kính cận trục để giả cầu sai.'});
add('chromatic_lens','Sắc sai: tiêu cự phụ thuộc bước sóng','Quang học','imaging',[p('wavelength','Bước sóng',400,700,550,'nm',10,0),p('curvature','Bán kính cong hai mặt',10,40,20,'cm',1)],[q('focal','Tiêu cự','cm'),q('index','Chiết suất theo Cauchy','',4),q('shift','Dời tiêu điểm so với 550 nm','mm')],'n(λ)=1,5+0,004/λ² (λ theo µm); f=R/[2(n−1)]',s=>{const index=1.5+.004/(s.wavelength/1000)**2,focal=s.curvature/(2*(index-1)),ref=s.curvature/(2*(.5+.004/.55**2));return {index,focal,shift:(focal-ref)*10};},'Ánh sáng xanh và đỏ hội tụ ở cùng một mặt phẳng ảnh không?',{view:'chromatic',limit:'Thấu kính mỏng hai mặt lồi bằng nhau; hệ số Cauchy giả định cho vật liệu minh họa, không đại diện một mã kính thương mại.'});
// 24. Distinct multi-path interference geometries.
add('thin_film','Màng mỏng và đảo pha phản xạ','Quang học','interferometer',[p('thickness','Bề dày màng',0,1000,200,'nm',10,0),p('index','Chiết suất màng',1.2,1.8,1.4,'',.05),p('wavelength','Bước sóng trong không khí',400,700,550,'nm',10,0)],[q('intensity','Cường độ phản xạ chuẩn hóa'),q('phase','Độ lệch pha gồm đảo pha','rad'),q('opticalPath','Chênh quang lộ','nm')],'Δφ=4πnd/λ+π; I≈(1+cosΔφ)/2',s=>{const opticalPath=2*s.index*s.thickness,phase=2*pi*opticalPath/s.wavelength+pi;return {opticalPath,phase,intensity:(1+Math.cos(phase))/2};},'Vì sao màng có bề dày tiến tới 0 lại tối trong phản xạ của mô hình này?',{view:'film',limit:'Màng chiết suất n nằm giữa không khí, tới vuông góc; chỉ hai chùm phản xạ đầu có biên độ xấp xỉ bằng nhau, một lần đổi pha π; cường độ đã chuẩn hóa.'});
add('newton_rings','Vân Newton trong phản xạ','Quang học','interferometer',[p('radius','Bán kính vị trí trên vòng vân',0,2,1,'mm',.05),p('curvature','Bán kính cong mặt kính',.2,2,1,'m',.1),p('wavelength','Bước sóng',400,700,550,'nm',10,0)],[q('intensity','Cường độ phản xạ chuẩn hóa'),q('order','Bậc vân tối liên tục'),q('firstDark','Bán kính vân tối thứ nhất','mm')],'rm²=mλR; I(r)≈sin²(πr²/(λR))',s=>{const order=(s.radius/1000)**2/(s.wavelength*1e-9*s.curvature);return {order,intensity:Math.sin(pi*order)**2,firstDark:Math.sqrt(s.wavelength*1e-9*s.curvature)*1000};},'Bình phương bán kính các vân tối liên tiếp có cách đều nhau không?',{view:'rings',limit:'Lớp không khí mỏng giữa mặt cầu và bản phẳng, tiếp xúc tại tâm; tới gần vuông góc, bỏ biến dạng và nhiều lần phản xạ.'});
add('michelson','Giao thoa kế Michelson: dịch gương đếm vân','Quang học','interferometer',[p('mirror','Độ dịch gương',0,3,1,'µm',.02),p('wavelength','Bước sóng',400,700,550,'nm',10,0)],[q('intensity','Cường độ tại đầu thu chuẩn hóa'),q('fringes','Số chu kì vân dịch từ mốc'),q('path','Chênh quang lộ tăng thêm','µm')],'Δquang lộ=2Δx; số vân=2Δx/λ',s=>({intensity:(1+Math.cos(4*pi*s.mirror/(s.wavelength/1000)))/2,fringes:2*s.mirror/(s.wavelength/1000),path:2*s.mirror}),'Vì sao gương dịch nửa bước sóng đã làm một chu kì vân đi qua đầu thu?',{view:'michelson',limit:'Hai nhánh cân bằng tại mốc x=0, nguồn đơn sắc kết hợp, gương dịch dọc nhánh; số vân có phần lẻ biểu diễn pha chứ không phải bộ đếm sự kiện.'});
add('fabry_perot','Khoang Fabry–Pérot và nhiều chùm truyền','Quang học','interferometer',[p('gap','Khoảng cách hai gương',.1,3,1,'µm',.02),p('reflectivity','Hệ số phản xạ công suất mỗi gương',.1,.8,.6,'',.05),p('wavelength','Bước sóng',400,700,550,'nm',10,0)],[q('transmission','Hệ số truyền công suất'),q('finesse','Độ tinh tế theo nửa cực đại'),q('freeRange','Khoảng phổ tự do','THz')],'T=1/[1+4R sin²(δ/2)/(1−R)²]; δ=4πd/λ',s=>{const delta=4*pi*s.gap/(s.wavelength/1000),F=4*s.reflectivity/(1-s.reflectivity)**2;return {transmission:1/(1+F*Math.sin(delta/2)**2),finesse:F>=1?pi/(2*Math.asin(1/Math.sqrt(F))):null,freeRange:c/(2*s.gap*1e-6)/1e12};},'Tăng độ phản xạ làm đỉnh truyền rộng hơn hay hẹp hơn?',{view:'cavity',limit:'Hai gương giống nhau không hấp thụ, không khí, tới vuông góc; công thức Airy cộng nhiều chùm, độ tinh tế theo bề rộng nửa cực đại chỉ xác định khi R ≥ 3−2√2; dưới ngưỡng này cực tiểu vẫn lớn hơn nửa cực đại.'});
add('fringe_visibility','Độ tương phản vân và độ kết hợp','Quang học','interferometer',[p('path','Chênh quang lộ',0,10,3,'mm',.2),p('coherence','Chiều dài kết hợp giả định',1,5,2,'mm',.2),p('ratio','Cường độ chùm 2 / chùm 1',.1,4,1,'',.1)],[q('visibility','Độ tương phản vân'),q('maximum','Cực đại / tổng cường độ riêng'),q('minimum','Cực tiểu / tổng cường độ riêng')],'V=2√(I₁I₂)|γ|/(I₁+I₂); |γ|=exp(−Δ²/(2Lc²))',s=>{const visibility=2*Math.sqrt(s.ratio)/(1+s.ratio)*Math.exp(-.5*(s.path/s.coherence)**2);return {visibility,maximum:1+visibility,minimum:1-visibility};},'Hai chùm còn giao nhau có đủ để quan sát vân rõ khi chênh quang lộ rất lớn không?',{view:'coherence',limit:'Độ kết hợp giả định dạng Gaussian, hai chùm cùng phân cực; cường độ chuẩn hóa, không suy ra phổ nguồn thực từ một số đo đơn lẻ.'});
// 25. Full diffraction patterns and polarization states.
function j1(x){if(Math.abs(x)<1e-9)return 0;const n=192,step=pi/n;let sum=0;for(let i=0;i<=n;i++)sum+=(i===0||i===n?1:i%2?4:2)*Math.cos(i*step-x*Math.sin(i*step));return sum*step/(3*pi);}
add('airy_pattern','Toàn bộ vân Airy qua khẩu độ tròn','Quang học','diffraction_pattern',[p('radial','Khoảng cách từ tâm ảnh',0,3,.5,'mm',.05),p('diameter','Đường kính khẩu độ',.5,3,1,'mm',.1),p('wavelength','Bước sóng',400,700,550,'nm',10,0)],[q('intensity','Cường độ chuẩn hóa'),q('firstDark','Bán kính vòng tối đầu','mm'),q('argument','Tọa độ chuẩn hóa u')],'I/I₀=[2J₁(u)/u]²; u=πD sinθ/λ',s=>{const z=pi*s.diameter/1000*(s.radial/1000)/Math.hypot(1,s.radial/1000)/(s.wavelength*1e-9);return {intensity:Math.abs(z)<1e-8?1:(2*j1(z)/z)**2,firstDark:1.22*s.wavelength*1e-9/(s.diameter/1000)*1000,argument:z};},'Các vòng sáng ngoài có cùng độ sáng với đĩa trung tâm không?',{view:'airy',limit:'Nhiễu xạ Fraunhofer, màn cách 1 m, khẩu độ tròn chiếu đều; J₁ được tích phân số, không thay bằng đường sin.'});
add('finite_double_slit','Hai khe hữu hạn và đường bao nhiễu xạ','Quang học','diffraction_pattern',[p('position','Vị trí trên màn',-6,6,1,'mm',.1),p('width','Bề rộng mỗi khe',.02,.15,.05,'mm',.01),p('separation','Khoảng cách tâm hai khe',.2,1,.5,'mm',.05)],[q('intensity','Cường độ tổng chuẩn hóa'),q('envelope','Đường bao một khe'),q('order','Tọa độ bậc giao thoa')],'I∝(sinβ/β)² cos²γ',s=>{const st=(s.position/1000)/Math.hypot(1,s.position/1000),beta=pi*s.width/1000*st/(550e-9),gamma=pi*s.separation/1000*st/(550e-9),envelope=sinc(beta)**2;return {envelope,intensity:envelope*Math.cos(gamma)**2,order:gamma/pi};},'Vì sao có những vị trí dự kiến sáng theo Young nhưng bị đường bao làm mờ hoặc mất?',{view:'double',limit:'Hai khe giống nhau, chiếu kết hợp cùng pha, λ=550 nm, màn 1 m; Fraunhofer, bỏ độ rộng phổ và kích thước nguồn.'});
add('grating_resolution','Phân giải hai vạch quang phổ bằng cách tử','Quang học','diffraction_pattern',[p('slits','Số khe được chiếu sáng',100,2000,500,'',100,0),p('order','Bậc phổ',1,3,1,'',1,0),p('difference','Chênh hai bước sóng',.01,5,1,'nm',.01)],[q('minimum','Chênh bước sóng nhỏ nhất','nm',4),q('resolution','Năng suất phân giải mN','',0),q('resolved','Đạt tiêu chí Rayleigh: 1','',0)],'R=λ/Δλ=mN',s=>{const resolution=Math.round(s.order)*Math.round(s.slits),minimum=550/resolution;return {resolution,minimum,resolved:s.difference>=minimum?1:0};},'Tăng số khe chiếu sáng giúp tách hai vạch gần nhau như thế nào?',{view:'grating',limit:'Bước sóng trung tâm 550 nm, cách tử lí tưởng; tiêu chí Rayleigh, không tính bề rộng khe vào, sai số quang học hay nhiễu đầu thu.'});
add('wave_plate','Bản trễ pha và phân cực elip','Quang học','diffraction_pattern',[p('angle','Góc phân cực tới với trục nhanh',0,90,45,'°',2),p('retardance','Độ trễ pha hai trục',0,360,90,'°',5)],[q('ellipticity','Góc elip χ','°'),q('orientation','Hướng trục lớn','°'),q('circular','Tham số Stokes S3 chuẩn hóa')],'S3=sin2θ sinδ; sin2χ=S3',s=>{const a=rad(s.angle),d=rad(s.retardance),circular=Math.sin(2*a)*Math.sin(d);return {circular,ellipticity:.5*deg(Math.asin(clamp(circular,-1,1))),orientation:.5*deg(Math.atan2(Math.sin(2*a)*Math.cos(d),Math.cos(2*a)))};},'Bản một phần tư bước sóng có luôn biến ánh sáng phân cực thẳng thành phân cực tròn không?',{view:'waveplate',limit:'Bản lưỡng chiết không hấp thụ, tới vuông góc, ánh sáng kết hợp; khi tròn, hướng trục lớn là quy ước không có ý nghĩa duy nhất.'});
add('photoelasticity','Quang đàn hồi giữa hai kính phân cực chéo','Quang học','diffraction_pattern',[p('stress','Chênh ứng suất chính',0,30,10,'MPa',1),p('thickness','Bề dày mẫu',1,10,5,'mm',.5),p('coefficient','Hệ số quang đàn hồi giả định',1,6,3,'10⁻¹² Pa⁻¹',.2)],[q('transmission','Cường độ truyền chuẩn hóa'),q('phase','Độ trễ pha','rad'),q('birefringence','Chênh chiết suất','10⁻⁶',2)],'Δn=Cσ; δ=2πΔn d/λ; I/I₀=sin²(δ/2)',s=>{const dn=s.coefficient*1e-12*s.stress*1e6,phase=2*pi*dn*s.thickness/1000/(550e-9);return {birefringence:dn*1e6,phase,transmission:Math.sin(phase/2)**2};},'Một mức sáng có xác định duy nhất ứng suất khi đã xuất hiện nhiều bậc vân không?',{view:'stress',limit:'Ứng suất phẳng đồng nhất, trục chính mẫu 45° so với phân cực, λ=550 nm; hệ số vật liệu giả định tuyến tính, không suy ra ứng suất công trình thực.'});
// 26. Heat transfer by several mechanisms.
add('convection_radiation','Làm nguội do đối lưu và bức xạ','Vật lí nhiệt','heat_transport',[p('emissivity','Hệ số phát xạ',.1,1,.8,'',.05),p('initial','Nhiệt độ vật ban đầu',350,500,420,'K',5,0),p('mass','Khối lượng vật',.2,2,1,'kg',.1)],[q('temperature','Nhiệt độ vật','K'),q('radiation','Công suất bức xạ thuần','W'),q('convection','Công suất đối lưu','W')],'mc dT/dt=−A[h(T−Tmt)+εσ(T⁴−Tmt⁴)]',s=>{const [temperature]=integrate(s.t,[s.initial],(_,y)=>[-.1*(8*(y[0]-300)+s.emissivity*sigma*(y[0]**4-300**4))/(s.mass*400)],1);return {temperature,radiation:s.emissivity*sigma*.1*(temperature**4-300**4),convection:.8*(temperature-300)};},'Hai cơ chế truyền nhiệt có phụ thuộc nhiệt độ theo cùng quy luật không?',{grade:12,time:true,window:400,view:'cooling',limit:'Nhiệt dung riêng 400 J/(kg·K), diện tích 0,1 m², h=8 W/(m²·K), môi trường 300 K; vật có nhiệt độ đồng đều; nghiệm RK4.'});
add('radiative_balance','Cân bằng hấp thụ và phát xạ nhiệt','Vật lí nhiệt','heat_transport',[p('absorptivity','Hệ số hấp thụ bức xạ tới',.1,1,.7,'',.05),p('emissivity','Hệ số phát xạ hồng ngoại',.1,1,.8,'',.05),p('intensity','Suất chiếu bức xạ',100,1500,800,'W/m²',50)],[q('temperature','Nhiệt độ cân bằng','K'),q('absorbed','Công suất hấp thụ trên diện tích','W/m²'),q('netEmission','Công suất bức xạ thuần trên diện tích','W/m²')],'αI=εσ(T⁴−Tmt⁴)',s=>{const absorbed=s.absorptivity*s.intensity,temperature=(absorbed/(s.emissivity*sigma)+300**4)**.25;return {temperature,absorbed,netEmission:s.emissivity*sigma*(temperature**4-300**4)};},'Vật hấp thụ tốt ánh sáng tới có nhất thiết cũng có cùng hệ số phát xạ trong hồng ngoại không?',{grade:12,view:'balance',limit:'Tấm phẳng một mặt nhận chiếu và phát xạ, môi trường 300 K; bỏ đối lưu và dẫn nhiệt; hai hệ số thuộc hai dải phổ khác nhau.'});
add('layered_wall','Dẫn nhiệt qua tường hai lớp','Vật lí nhiệt','heat_transport',[p('thickness1','Bề dày lớp 1',.01,.2,.05,'m',.01),p('conductivity1','Hệ số dẫn nhiệt lớp 1',.05,1,.2,'W/(m·K)',.05),p('thickness2','Bề dày lớp 2',.02,.4,.15,'m',.01),p('conductivity2','Hệ số dẫn nhiệt lớp 2',.1,2,.8,'W/(m·K)',.1)],[q('flux','Mật độ dòng nhiệt','W/m²'),q('interface','Nhiệt độ mặt phân cách','°C'),q('thermalResistance','Điện trở nhiệt trên đơn vị diện tích','m²·K/W')],'j=(Tnóng−Tlạnh)/(d₁/k₁+d₂/k₂)',s=>{const thermalResistance=s.thickness1/s.conductivity1+s.thickness2/s.conductivity2,flux=20/thermalResistance;return {thermalResistance,flux,interface:30-flux*s.thickness1/s.conductivity1};},'Nhiệt độ giảm nhiều hơn trên lớp có điện trở nhiệt lớn hay nhỏ?',{grade:12,extra:false,view:'wall',limit:'Trạng thái ổn định một chiều, mặt nóng 30 °C và lạnh 10 °C; tiếp xúc hoàn hảo, không phát nhiệt bên trong.'});
add('transient_heat_bar','Thanh dẫn nhiệt: suy giảm phân bố ban đầu','Vật lí nhiệt','heat_transport',[p('diffusivity','Hệ số khuếch tán nhiệt',.5,5,2,'10⁻⁵ m²/s',.1),p('length','Chiều dài thanh',.1,1,.4,'m',.05),p('probe','Vị trí đầu dò / chiều dài',.1,.9,.4,'',.05)],[q('temperature','Nhiệt độ đầu dò','°C'),q('heatFlux','Mật độ dòng nhiệt có dấu','W/m²'),q('amplitude','Biên độ chênh nhiệt còn lại','K')],'T(x,t)=20+80sin(πx/L)exp(−απ²t/L²)',s=>{const alpha=s.diffusivity*1e-5,amplitude=80*Math.exp(-alpha*pi*pi*s.t/s.length**2);return {amplitude,temperature:20+amplitude*Math.sin(pi*s.probe),heatFlux:-3.5e6*alpha*amplitude*pi/s.length*Math.cos(pi*s.probe),tau:s.length**2/(alpha*pi*pi)};},'Tại tâm thanh, gradient nhiệt bằng 0 có đồng nghĩa nhiệt độ không giảm theo thời gian không?',{grade:12,time:true,duration:(s,d)=>5*d.tau,view:'bar',limit:'Hai đầu giữ 20 °C, ban đầu T=20+80sin(πx/L); nghiệm chính xác một mode phương trình nhiệt; nhiệt dung thể tích 3,5 MJ/(m³·K), không tổn hao qua thành.'});
add('seebeck','Suất nhiệt điện Seebeck','Vật lí nhiệt','heat_transport',[p('difference','Chênh nhiệt hai mối nối',-100,100,50,'K',5),p('coefficient','Hệ số Seebeck tương đối',10,50,30,'µV/K',2),p('resistance','Điện trở toàn vòng',1,20,5,'Ω',1)],[q('emf','Suất điện động có dấu','mV'),q('current','Dòng trong vòng','mA'),q('power','Công suất tỏa nhiệt','µW')],'E≈SabΔT',s=>{const emf=s.coefficient*s.difference/1000;return {emf,current:emf/s.resistance,power:emf*emf/s.resistance};},'Đảo nóng–lạnh hai mối nối làm đổi chiều dòng và dấu suất điện động ra sao?',{grade:12,view:'thermocouple',limit:'Hai vật liệu có hệ số Seebeck tương đối giả định không đổi; bỏ hiệu ứng Peltier, Thomson và phản hồi nhiệt do dòng.'});
// 27. Thermodynamic cycles, not just a Carnot efficiency label.
add('otto_cycle','Chu trình Otto lí tưởng','Vật lí nhiệt','heat_cycle',[p('compression','Tỉ số nén',2,12,8,'',.5),p('peak','Nhiệt độ cao nhất',900,2000,1500,'K',50,0)],[q('efficiency','Hiệu suất','%'),q('work','Công một chu trình','J'),q('afterCompression','Nhiệt độ sau nén','K')],'η=1−r⁽¹⁻γ⁾; nén–giãn đoạn nhiệt, cấp–thải nhiệt đẳng tích',s=>{const a=s.compression**.4,T2=300*a,T4=s.peak/a,heatIn=.1*R/.4*(s.peak-T2),heatOut=.1*R/.4*(T4-300);return {efficiency:100*(1-1/a),work:heatIn-heatOut,afterCompression:T2,t2:T2,t3:s.peak,t4:T4,ratio:s.compression};},'Tăng tỉ số nén ảnh hưởng hiệu suất và nhiệt độ cuối nén như thế nào?',{grade:12,view:'otto',limit:'0,1 mol khí lí tưởng γ=1,4, T₁=300 K; chu trình chuẩn không khí, không cháy, không ma sát hay truyền nhiệt ngoài hai giai đoạn quy định.'});
add('diesel_cycle','Chu trình Diesel và tỉ số cắt','Vật lí nhiệt','heat_cycle',[p('cutoff','Tỉ số cắt thể tích',1.1,3,2,'',.1),p('compression','Tỉ số nén',5,20,12,'',.5)],[q('efficiency','Hiệu suất','%'),q('work','Công một chu trình','J'),q('peak','Nhiệt độ sau cấp nhiệt','K')],'η=1−(ρ^γ−1)/[γ(ρ−1)r⁽γ−1⁾]',s=>{const T2=300*s.compression**.4,T3=T2*s.cutoff,T4=T3*(s.cutoff/s.compression)**.4,Qin=.1*R*1.4/.4*(T3-T2),Qout=.1*R/.4*(T4-300);return {efficiency:100*(1-Qout/Qin),work:Qin-Qout,peak:T3,t2:T2,t3:T3,t4:T4,ratio:s.compression};},'Ở cùng tỉ số nén, kéo dài giai đoạn cấp nhiệt đẳng áp làm hiệu suất đổi thế nào?',{grade:12,view:'diesel',limit:'0,1 mol khí γ=1,4, T₁=300 K; 1<ρ<r; chu trình không khí lí tưởng, không mô hình cháy.'});
add('stirling_regenerator','Chu trình Stirling và bộ hồi nhiệt','Vật lí nhiệt','heat_cycle',[p('regeneration','Hiệu quả hồi nhiệt',0,1,.8,'',.05),p('hot','Nhiệt độ nguồn nóng',400,900,600,'K',20),p('cold','Nhiệt độ nguồn lạnh',250,350,300,'K',10),p('ratio','Tỉ số thể tích',1.2,4,2,'',.1)],[q('efficiency','Hiệu suất','%'),q('work','Công một chu trình','J'),q('extraHeat','Nhiệt cấp bù do hồi nhiệt chưa đủ','J')],'W=nR(Th−Tc)lnr; Qin=nRThlnr+(1−ε)nCv(Th−Tc)',s=>{const work=.1*R*(s.hot-s.cold)*Math.log(s.ratio),extraHeat=(1-s.regeneration)*.1*1.5*R*(s.hot-s.cold),Qin=.1*R*s.hot*Math.log(s.ratio)+extraHeat;return {work,extraHeat,efficiency:100*work/Qin};},'Chỉ khi hồi nhiệt hoàn hảo, hiệu suất mới đạt giới hạn Carnot trong các giả định này vì sao?',{grade:12,view:'stirling',limit:'0,1 mol khí đơn nguyên tử; hai nhánh đẳng nhiệt, hai nhánh đẳng tích, hồi nhiệt hiệu quả ε; bỏ ma sát và tổn hao khác.'});
add('refrigerator','Tủ lạnh: hệ số COP và công tiêu thụ','Vật lí nhiệt','heat_cycle',[p('cold','Nhiệt độ ngăn lạnh',250,290,270,'K',2),p('hot','Nhiệt độ nơi thải nhiệt',300,330,310,'K',2),p('performance','COP / COP Carnot',.2,1,.5,'',.05),p('heat','Nhiệt lấy khỏi ngăn lạnh',100,1000,500,'J',50)],[q('cop','Hệ số làm lạnh COP'),q('work','Công cần cấp','J'),q('rejected','Nhiệt thải ra ngoài','J')],'COP=Qc/W; COPCarnot=Tc/(Th−Tc)',s=>{const cop=s.performance*s.cold/(s.hot-s.cold),work=s.heat/cop;return {cop,work,rejected:s.heat+work};},'COP lớn hơn 1 có vi phạm bảo toàn năng lượng không?',{grade:12,view:'refrigerator',limit:'Hai nguồn nhiệt cố định; COP thực được tham số hóa bằng tỉ phần giới hạn Carnot; đường p–V minh họa chu trình Carnot ngược lí tưởng, không biểu diễn phần công tăng thêm do tổn hao; không mô hình môi chất hay máy nén thực.'});
add('brayton_cycle','Chu trình Brayton và công nén','Vật lí nhiệt','heat_cycle',[p('pressureRatio','Tỉ số áp suất',2,10,5,'',.5),p('hot','Nhiệt độ vào turbine',1000,1600,1300,'K',50,0)],[q('efficiency','Hiệu suất','%'),q('work','Công thuần một chu trình','J'),q('compressor','Công nén cần cấp','J')],'η=1−rp⁻⁽γ−1⁾ᐟγ',s=>{const a=s.pressureRatio**(.4/1.4),T2=300*a,T4=s.hot/a,compressor=.1*3.5*R*(T2-300),turbine=.1*3.5*R*(s.hot-T4);return {efficiency:100*(1-1/a),work:turbine-compressor,compressor,t2:T2,t3:s.hot,t4:T4,ratio:s.pressureRatio};},'Vì sao công turbine không bằng công thuần cấp cho tải?',{grade:12,view:'brayton',limit:'0,1 mol khí γ=1,4, vào máy nén 300 K; nén/giãn đoạn nhiệt thuận nghịch, cấp/thải nhiệt đẳng áp; bỏ tổn thất áp và cơ học.'});
