add('maxwell_distribution','Phân bố tốc độ Maxwell–Boltzmann','Khí lí tưởng','thermal_statistics',[p('speed','Tốc độ khảo sát',0,2000,500,'m/s',20),p('temperature','Nhiệt độ tuyệt đối',200,800,300,'K',10,0),p('molarMass','Khối lượng mol',2,40,28,'g/mol',2)],[q('density','Mật độ xác suất tốc độ','s/m',6),q('mostProbable','Tốc độ có xác suất lớn nhất','m/s'),q('rms','Tốc độ căn quân phương','m/s')],'f(v)=4π(m/(2πkT))³ᐟ²v²exp(−mv²/(2kT))',s=>{const M=s.molarMass/1000,a=M/(2*R*s.temperature);return {density:4/pi**.5*a**1.5*s.speed**2*Math.exp(-a*s.speed**2),mostProbable:Math.sqrt(2*R*s.temperature/M),rms:Math.sqrt(3*R*s.temperature/M)};},'Vị trí đỉnh phân bố có trùng tốc độ căn quân phương không?',{grade:12,view:'maxwell',limit:'Khí lí tưởng cân bằng nhiệt, phân bố tốc độ (không phải thành phần vận tốc); mật độ xác suất phải nhân khoảng dv mới thành xác suất.'});
add('two_level_boltzmann','Hai mức năng lượng và phân bố Boltzmann','Khí lí tưởng','thermal_statistics',[p('temperature','Nhiệt độ',10,1000,300,'K',10,0),p('gap','Độ chênh năng lượng',1,100,30,'meV',2),p('degeneracy','Độ suy biến trên / dưới',1,5,1,'',1,0)],[q('upper','Tỉ phần ở mức trên'),q('ratio','Số hạt trên / dưới'),q('mean','Năng lượng trung bình trên mức gốc','meV')],'N₂/N₁=(g₂/g₁)exp(−ΔE/(kT))',s=>{const ratio=Math.round(s.degeneracy)*Math.exp(-s.gap*.001*qe/(kB*s.temperature)),upper=ratio/(1+ratio);return {ratio,upper,mean:s.gap*upper};},'Ở nhiệt độ rất cao, hai mức có luôn được chiếm bằng nhau khi độ suy biến khác nhau không?',{grade:12,view:'levels',limit:'Các hạt độc lập ở cân bằng, chỉ hai mức năng lượng, thống kê Boltzmann; chưa xét tương tác hay Bose–Einstein/Fermi–Dirac.'});
function seeded(seed){let x=(Math.round(seed)*2654435761)>>>0;return ()=>{x=(1664525*x+1013904223)>>>0;return (x+.5)/4294967296;};}
function bridgeNormal(seed,interval,axis,node){let x=(seed^Math.imul(interval+1,0x9e3779b9)^Math.imul(axis+1,0x85ebca6b)^Math.imul(node+1,0xc2b2ae35))>>>0;const uniform=()=>{x=(x+0x6d2b79f5)>>>0;let z=x;z=Math.imul(z^(z>>>15),z|1);z^=z+Math.imul(z^(z>>>7),z|61);return (((z^(z>>>14))>>>0)+.5)/4294967296;};return Math.sqrt(-2*Math.log(uniform()))*Math.cos(2*pi*uniform());}
function brownian(t,D,seed){const dt=.05,n=Math.floor(t/dt),frac=t/dt-n,rng=seeded(seed),y=[0,0,0],scale=Math.sqrt(2*D*dt);for(let j=0;j<=n;j++)for(let axis=0;axis<3;axis++){const z=Math.sqrt(-2*Math.log(rng()))*Math.cos(2*pi*rng());if(j<n)y[axis]+=scale*z;else{let bridge=0;for(let level=0;level<18;level++){const count=2**level,k=Math.floor(frac*count),local=frac*count-k;bridge+=2**(-(level+2)/2)*2*Math.min(local,1-local)*bridgeNormal(seed,n,axis,count+k);}y[axis]+=scale*(frac*z+bridge);}}return y;}
add('brownian_motion','Chuyển động Brown và độ dời bình phương','Khí lí tưởng','thermal_statistics',[p('diffusion','Hệ số khuếch tán',.1,5,1,'µm²/s',.1),p('seed','Mẫu ngẫu nhiên',1,100,7,'',1,0)],[q('msd','Bình phương độ dời kì vọng 3D','µm²'),q('x','Độ dời x của một quỹ đạo','µm'),q('sample','Bình phương độ dời mẫu','µm²')],'⟨r²⟩=6Dt trong ba chiều',s=>{const [x,y,z]=brownian(s.t,s.diffusion,s.seed);return {x,y,z,msd:6*s.diffusion*s.t,sample:x*x+y*y+z*z};},'Một quỹ đạo có luôn thỏa đúng r²=6Dt tại mọi thời điểm không?',{grade:12,time:true,view:'brownian',limit:'Quỹ đạo Gaussian mô phỏng gần đúng: bước 0,05 s, cầu Brown 18 mức giữa bước; mẫu gieo hạt cố định để xem lại; 6Dt là trung bình quần thể, không là quỹ đạo từng hạt.'});
add('vapor_pressure','Áp suất hơi và Clausius–Clapeyron','Vật lí nhiệt','thermal_statistics',[p('temperature','Nhiệt độ tuyệt đối',280,400,330,'K',5,0),p('latent','Nhiệt hóa hơi mol giả định',20,60,40.7,'kJ/mol',1)],[q('pressure','Áp suất hơi bão hòa gần đúng','kPa'),q('logRatio','ln(p/p₀)'),q('ratio','Tỉ số p/p₀')],'ln(p/p₀)=−L/R·(1/T−1/T₀)',s=>{const logRatio=-s.latent*1000/R*(1/s.temperature-1/373.15),ratio=Math.exp(logRatio);return {logRatio,ratio,pressure:101.325*ratio};},'Vì sao đồ thị ln p theo 1/T gần thẳng hơn đồ thị p theo T?',{grade:12,view:'vapor',limit:'Gần đúng nhiệt hóa hơi mol không đổi và hơi lí tưởng; mốc p₀=101,325 kPa tại 373,15 K; không phải bảng tra chính xác của nước trong toàn miền.'});
add('van_der_waals','Đẳng nhiệt khí Van der Waals','Khí lí tưởng','thermal_statistics',[p('volume','Thể tích mol',.15,2,.3,'L/mol',.01),p('temperature','Nhiệt độ tuyệt đối',250,500,300,'K',10,0)],[q('pressure','Áp suất mô hình','bar'),q('ideal','Áp suất khí lí tưởng','bar'),q('stable','Nhánh có dP/dV<0: 1','',0)],'p=RT/(Vm−b)−a/Vm²',s=>{const V=s.volume/1000,a=.364,b=4.267e-5,dp=-R*s.temperature/(V-b)**2+2*a/V**3;return {pressure:(R*s.temperature/(V-b)-a/V**2)/1e5,ideal:R*s.temperature/V/1e5,stable:dp<0?1:0};},'Nhánh có độ dốc dương có thể được xem là cân bằng một pha bền không?',{grade:12,view:'vdw',limit:'a=0,364 Pa·m⁶/mol², b=4,267×10⁻⁵ m³/mol; chỉ phương trình pha đồng nhất, chưa dùng dựng Maxwell để tìm cân bằng lỏng–hơi.'});
