add('hydrogen_lines','Chuyển mức hydrogen và phổ vạch','Vật lí hiện đại','quantum',[p('initial','Mức n ban đầu',2,10,3,'',1,0),p('final','Mức n cuối',1,5,2,'',1,0)],[q('wavelength','Bước sóng photon phát','nm'),q('energy','Năng lượng photon phát','eV'),q('frequency','Tần số photon phát','THz')],'En=−13,605693/n² eV',s=>{const ni=Math.round(s.initial),nf=Math.round(s.final),energy=ni>nf?13.605693*(1/nf**2-1/ni**2):null;return {energy,wavelength:energy===null?null:h*c/(energy*qe)*1e9,frequency:energy===null?null:energy*qe/h/1e12,allowed:energy===null?0:1,ni,nf};},'Mọi cặp mức nhập vào có đều tương ứng phát photon không?',{grade:12,view:'hydrogen',limit:'Hydrogen không xét cấu trúc tinh tế; chỉ phát xạ khi ni>nf, không mô hình cường độ hay xác suất chuyển mức.'});
add('franck_hertz','Franck–Hertz: mất năng lượng theo lượng','Vật lí hiện đại','quantum',[p('voltage','Điện áp tăng tốc electron',0,30,12,'V',.5),p('excitation','Năng lượng kích thích của khí',3,8,4.9,'eV',.1)],[q('remaining','Năng lượng còn lại sau số kích thích tối đa','eV'),q('collisions','Số kích thích tối đa','',0),q('photon','Bước sóng nếu mức đó phát về gốc','nm')],'Kcòn=eU−nΔE; n=floor(eU/ΔE)',s=>{const collisions=Math.floor(s.voltage/s.excitation);return {collisions,remaining:s.voltage-collisions*s.excitation,photon:h*c/(s.excitation*qe)*1e9};},'Tăng điện áp liên tục có làm năng lượng truyền trong từng kích thích biến thiên liên tục không?',{grade:12,view:'franck',limit:'Mô hình ngân sách năng lượng qua số va chạm kích thích tối đa; không dự đoán đường dòng–áp thực, tiết diện va chạm hay quãng đường tự do.'});
add('compton_scattering','Tán xạ Compton và năng lượng giật lùi','Vật lí hiện đại','quantum',[p('angle','Góc tán xạ photon',0,180,90,'°',5),p('wavelength','Bước sóng photon tới',1,20,5,'pm',.5)],[q('shift','Độ tăng bước sóng','pm',4),q('scattered','Năng lượng photon ra','keV'),q('recoil','Động năng electron giật lùi','keV')],'Δλ=h(1−cosθ)/(mec)',s=>{const shift=h/(me*c)*(1-Math.cos(rad(s.angle)))*1e12,initial=h*c/(s.wavelength*1e-12)/qe/1000,scattered=h*c/((s.wavelength+shift)*1e-12)/qe/1000;return {shift,scattered,recoil:initial-scattered};},'Photon tán xạ góc lớn mất nhiều hay ít năng lượng hơn?',{grade:12,view:'compton',limit:'Electron tự do ban đầu đứng yên; công thức Compton tương đối tính, bỏ liên kết và các quá trình hấp thụ cạnh tranh.'});
add('electron_bragg','Electron nhiễu xạ trên mặt tinh thể','Vật lí hiện đại','quantum',[p('voltage','Điện áp tăng tốc',1000,20000,5000,'V',500,0),p('spacing','Khoảng cách mặt mạng',.02,.5,.1,'nm',.01),p('order','Bậc nhiễu xạ',1,3,1,'',1,0)],[q('wavelength','Bước sóng electron','pm'),q('angle','Góc Bragg','°'),q('scattering','Góc lệch giữa hai tia','°')],'λ=hc/√(K(K+2mec²)); 2d sinθ=nλ',s=>{const K=qe*s.voltage,wavelength=h*c/Math.sqrt(K*(K+2*me*c*c)),v=Math.round(s.order)*wavelength/(2*s.spacing*1e-9),angle=v<=1?deg(Math.asin(v)):null;return {wavelength:wavelength*1e12,angle,scattering:angle===null?null:2*angle,allowed:v<=1?1:0};},'Khi nλ lớn hơn 2d, vì sao bậc phản xạ ấy không có góc thực?',{grade:12,view:'bragg',limit:'Electron qua hiệu điện thế từ gần đứng yên; động lượng dùng công thức tương đối tính; tinh thể lí tưởng, không mô hình cường độ các mặt mạng.'});
add('quantum_box','Giếng thế: năng lượng và mật độ xác suất','Vật lí hiện đại','quantum',[p('position','Vị trí x/L',0,1,.3,'',.02),p('level','Số lượng tử n',1,5,2,'',1,0),p('length','Bề rộng giếng',.5,3,1,'nm',.1)],[q('density','Mật độ xác suất','nm⁻¹',4),q('energy','Năng lượng trạng thái','eV',4),q('cumulative','Xác suất từ 0 tới x')],'En=n²h²/(8mL²); |ψ|²=2sin²(nπx/L)/L',s=>{const n=Math.round(s.level);return {density:2/s.length*Math.sin(n*pi*s.position)**2,energy:n*n*h*h/(8*me*(s.length*1e-9)**2)/qe,cumulative:s.position-Math.sin(2*n*pi*s.position)/(2*n*pi)};},'Các điểm mật độ xác suất bằng 0 có phải vị trí electron dừng lại trên quỹ đạo không?',{grade:12,view:'box',limit:'Electron trong giếng thế vuông vô hạn một chiều; trạng thái riêng, mật độ xác suất không đổi theo thời gian; không có quỹ đạo cổ điển.'});
