add('decay_chain','Chuỗi phân rã mẹ–con','Hạt nhân','nuclear',[p('parentHalf','Chu kì bán rã mẹ',.2,5,2,'s',.1),p('daughterHalf','Chu kì bán rã con',.2,5,1,'s',.1)],[q('parent','Số hạt mẹ kì vọng','',2),q('daughter','Số hạt con kì vọng','',2),q('stable','Số hạt bền cuối kì vọng','',2)],'Nd=N₀λm(e⁻λmᵗ−e⁻λdᵗ)/(λd−λm)',s=>{const a=Math.LN2/s.parentHalf,b=Math.LN2/s.daughterHalf,parent=1000*Math.exp(-a*s.t),daughter=Math.abs(a-b)<1e-10?1000*a*s.t*Math.exp(-a*s.t):1000*a*(Math.exp(-a*s.t)-Math.exp(-b*s.t))/(b-a);return {parent,daughter,stable:1000-parent-daughter};},'Số hạt con có thể tăng trong khi bản thân chúng vẫn đang phân rã không?',{grade:12,time:true,duration:s=>8*Math.max(s.parentHalf,s.daughterHalf),view:'chain',limit:'Ban đầu 1000 hạt mẹ và không có hạt con; mẹ→con→bền, nhánh duy nhất; số đọc là kì vọng, xử lí riêng hai hằng số phân rã bằng nhau.'});
add('alpha_recoil','Phân rã alpha và giật lùi hạt nhân con','Hạt nhân','nuclear',[p('massNumber','Số khối hạt nhân mẹ',100,240,210,'',2,0),p('energy','Năng lượng Q',1,10,5,'MeV',.2)],[q('alpha','Động năng hạt alpha','MeV'),q('daughter','Động năng hạt nhân con','MeV'),q('momentum','Độ lớn động lượng mỗi hạt','MeV/c')],'Kα≈Q(A−4)/A; Kcon≈4Q/A',s=>{const alpha=s.energy*(s.massNumber-4)/s.massNumber;return {alpha,daughter:4*s.energy/s.massNumber,momentum:Math.sqrt(2*4*931.494102*alpha)};},'Vì sao hạt nhẹ hơn nhận phần động năng lớn hơn khi hai động lượng đối nhau?',{grade:12,view:'alpha',limit:'Mẹ đứng yên, phân rã hai vật, khối lượng gần A u và (A−4)u; phi tương đối tính, bỏ photon; thông số giả định, không gán cho đồng vị thực.'});
add('reaction_threshold','Năng lượng Q và ngưỡng phản ứng','Hạt nhân','nuclear',[p('defect','Khối lượng trước trừ sau',-.01,.01,-.004,'u',.001,3),p('target','Khối lượng bia / khối lượng hạt tới',1,40,12,'',1,0),p('incident','Động năng hạt tới',0,20,8,'MeV',.5)],[q('qValue','Năng lượng Q','MeV'),q('threshold','Ngưỡng gần đúng','MeV'),q('available','Động năng tổng sau nếu đủ ngưỡng','MeV')],'Q=Δmc²; Kngưỡng≈−Q(1+m/M) nếu Q<0',s=>{const qValue=s.defect*931.494102,threshold=qValue<0?-qValue*(1+1/s.target):0;return {qValue,threshold,available:s.incident>=threshold?s.incident+qValue:null,allowed:s.incident>=threshold?1:0};},'Năng lượng hạt tới chỉ lớn hơn |Q| đã chắc đủ ngưỡng khi bia đứng yên chưa?',{grade:12,view:'reaction',limit:'Phản ứng hai vật, bia đứng yên, ngưỡng phi tương đối tính; không xét rào Coulomb, tiết diện hay xác suất phản ứng; không đại diện kênh đồng vị cụ thể.'});
add('gamma_attenuation','Suy giảm gamma chùm hẹp qua vật liệu','Hạt nhân','nuclear',[p('thickness','Bề dày vật liệu',0,20,5,'cm',.5),p('attenuation','Hệ số suy giảm tuyến tính',.01,2,.2,'cm⁻¹',.01),p('initial','Số photon tới kì vọng',100,10000,1000,'',100,0)],[q('transmitted','Số photon sơ cấp ra kì vọng'),q('fraction','Phần trăm photon còn trong chùm','%'),q('halfLayer','Lớp làm giảm một nửa','cm')],'I=I₀e⁻µx; HVL=ln2/µ',s=>({transmitted:s.initial*Math.exp(-s.attenuation*s.thickness),fraction:100*Math.exp(-s.attenuation*s.thickness),halfLayer:Math.LN2/s.attenuation}),'Hai lớp dày bằng nhau làm giảm cùng một số photon hay cùng một tỉ phần?',{grade:12,view:'attenuation',limit:'Chùm hẹp đơn năng, hệ số µ do người học chọn, không tích lũy photon tán xạ; không dùng làm tính toán liều hoặc thiết kế che chắn thực.'});
add('poisson_counting','Số đếm phóng xạ và dao động Poisson','Hạt nhân','nuclear',[p('seed','Lần lấy mẫu',1,100,1,'',1,0),p('rate','Tốc độ đếm kì vọng',.1,20,5,'s⁻¹',.5),p('interval','Thời gian cửa sổ',.1,2,1,'s',.1)],[q('count','Số đếm trong mẫu','',0),q('expected','Số đếm kì vọng λ'),q('sigma','Độ lệch chuẩn √λ')],'P(N=n)=e⁻λ λⁿ/n!; Var(N)=λ',s=>{const expected=s.rate*s.interval,rng=seeded(s.seed),L=Math.exp(-expected);let n=0,z=1;do{n++;z*=rng();}while(z>L&&n<1000);return {count:n-1,expected,sigma:Math.sqrt(expected)};},'Vì sao đếm lâu hơn giúp giảm sai số tương đối dù độ lệch chuẩn tuyệt đối tăng?',{grade:12,discrete:true,view:'counting',limit:'Quá trình Poisson tốc độ không đổi, không phông hay thời gian chết; mẫu giả ngẫu nhiên có hạt để xem lại; không mô tả toàn bộ sai số thiết bị.'});
export const expansionExperiments=specs;
